	(104, 'widget_block', 'a:89:{i:2;a:1:{s:7:"content";s:19:"<!-- wp:search /-->";}i:3;a:1:{s:7:"content";s:154:"<!-- wp:group --><div class="wp-block-group"><!-- wp:heading --><h2>Recent Posts</h2><!-- /wp:heading --><!-- wp:latest-posts /--></div><!-- /wp:group -->";}i:4;a:1:{s:7:"content";s:227:"<!-- wp:group --><div class="wp-block-group"><!-- wp:heading --><h2>Recent Comments</h2><!-- /wp:heading --><!-- wp:latest-comments {"displayAvatar":false,"displayDate":false,"displayExcerpt":false} /--></div><!-- /wp:group -->";}i:5;a:1:{s:7:"content";s:146:"<!-- wp:group --><div class="wp-block-group"><!-- wp:heading --><h2>Archives</h2><!-- /wp:heading --><!-- wp:archives /--></div><!-- /wp:group -->";}i:6;a:1:{s:7:"content";s:150:"<!-- wp:group --><div class="wp-block-group"><!-- wp:heading --><h2>Categories</h2><!-- /wp:heading --><!-- wp:categories /--></div><!-- /wp:group -->";}i:8;a:1:{s:7:"content";s:107:"<div id="pst-container">\n						<div>Philippine Standard Time:</div><div id="pst-time"></div>\n					   </div>";}i:11;a:1:{s:7:"content";s:237:"<!-- wp:image -->\n<figure class="wp-block-image"><img src="http://localhost/wp-content/themes/gwt-wordpress-26.0.0/images/transparency-seal-160x160.png" alt="transparency seal logo" title="Transparency Seal"/></figure>\n<!-- /wp:image -->";}i:12;a:1:{s:7:"content";s:285:"<!-- wp:paragraph -->\n<p>The DA-CBC supports the Philippines\' Transparency Seal mandate by ensuring openness in our research. We enhance crop productivity and sustainability, providing accessible information to improve food security and farmers\' livelihoods.</p>\n<!-- /wp:paragraph -->";}i:13;a:1:{s:7:"content";s:332:"<!-- wp:image {"id":133,"width":"157px","height":"auto","sizeSlug":"full","linkDestination":"none"} -->\n<figure class="wp-block-image size-full is-resized"><img src="http://localhost/wp-content/uploads/2024/05/transparency-seal-160x160-1.png" alt="" class="wp-image-133" style="width:157px;height:auto"/></figure>\n<!-- /wp:image -->";}i:15;a:1:{s:7:"content";s:237:"<!-- wp:image -->\n<figure class="wp-block-image"><img src="http://localhost/wp-content/themes/gwt-wordpress-26.0.0/images/transparency-seal-160x160.png" alt="transparency seal logo" title="Transparency Seal"/></figure>\n<!-- /wp:image -->";}i:16;a:1:{s:7:"content";s:285:"<!-- wp:paragraph -->\n<p>The DA-CBC supports the Philippines\' Transparency Seal mandate by ensuring openness in our research. We enhance crop productivity and sustainability, providing accessible information to improve food security and farmers\' livelihoods.</p>\n<!-- /wp:paragraph -->";}i:17;a:1:{s:7:"content";s:285:"<!-- wp:paragraph -->\n<p>The DA-CBC supports the Philippines\' Transparency Seal mandate by ensuring openness in our research. We enhance crop productivity and sustainability, providing accessible information to improve food security and farmers\' livelihoods.</p>\n<!-- /wp:paragraph -->";}i:18;a:1:{s:7:"content";s:52:"<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->";}i:19;a:1:{s:7:"content";s:522:"<div class="flex flex-col items-center gap-2">\n<a href=""><img id="tp-seal" src="/wp-content/themes/gwt-wordpress-26.0.0/images/transparency-seal-160x160.png" alt="transparency seal logo" title="Transparency Seal"></a>\n<p class="sm:block hidden text-justify sm:text-md text-sm">The DA-CBC supports the Philippines\' Transparency Seal mandate by ensuring openness in our research. We enhance crop productivity and sustainability, providing accessible information to improve food security and farmers\' livelihoods.</p>\n</div>";}i:20;a:1:{s:7:"content";s:665:"<div class="flex flex-col items-center gap-2"><a href="https://www.foi.gov.ph/"><img id="foi-logo" src="/wp-content/themes/gwt-wordpress-26.0.0/images/foi-logo-160x160.png" alt="freedom of infromation logo" title="Freedom of Information"></a>\n<p class="sm:block hidden text-justify sm:text-md text-sm">Embracing the principles of the Freedom of Information (FOI) bill, we\'re committed to openness and accountability in our research endeavors. Explore how we uphold transparency, providing accessible information to empower stakeholders and advance agricultural innovation. Join us as we pave the way for a more informed and engaged agricultural community.</p></div>";}i:21;a:1:{s:7:"content";s:52:"<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->";}i:23;a:1:{s:7:"content";s:135:"<!-- wp:paragraph {"align":"left"} -->\n<p class="has-text-align-left">Like and follow our Facebook account. </p>\n<!-- /wp:paragraph -->";}i:24;a:1:{s:7:"content";s:331:"<!-- wp:social-links {"align":"right","layout":{"type":"flex","justifyContent":"left"}} -->\n<ul class="wp-block-social-links alignright"><!-- wp:social-link {"url":"https://www.facebook.com/DACropBiotechCenter","service":"facebook","label":"DA-CBC Facebook Link","className":"text-white bg-red"} /--></ul>\n<!-- /wp:social-links -->";}i:25;a:1:{s:7:"content";s:67:"<!-- wp:embed {"providerNameSlug":"twitter","responsive":true} /-->";}i:27;a:1:{s:7:"content";s:346:"<!-- wp:widget-group -->\n<h2 class="widget-title"></h2><div class="wp-widget-group__inner-blocks"><!-- wp:columns -->\n<div class="wp-block-columns"></div>\n<!-- /wp:columns -->\n\n<!-- wp:social-links -->\n<ul class="wp-block-social-links"><!-- wp:social-link {"service":"facebook"} /--></ul>\n<!-- /wp:social-links --></div>\n<!-- /wp:widget-group -->";}i:29;a:1:{s:7:"content";s:750:"<div class="relative flex flex-col gap-2 w-auto h-fit">\n  <p class="font-semibold text-sm">Official Launch of the New DA-CBC Logo</p>\n  <div class="relative w-full shadow" style="padding-bottom: 56.25%;">\n    <iframe class="absolute top-0 left-0 w-full h-full border-none rounded" \n      src="https://www.facebook.com/plugins/video.php?height=314&href=https%3A%2F%2Fwww.facebook.com%2FDACropBiotechCenter%2Fvideos%2F2629670060546947%2F&show_text=false&width=560&t=0"\n      style="border:none;overflow:hidden; margin: 0 auto;" \n      scrolling="no" \n      frameborder="0" \n      allowf