	(3107, '_transient_feed_9bbd59226dc36b9b26cd43f15694c5c3', 'a:4:{s:5:"child";a:1:{s:0:"";a:1:{s:3:"rss";a:1:{i:0;a:6:{s:4:"data";s:3:"\n\n\n";s:7:"attribs";a:1:{s:0:"";a:1:{s:7:"version";s:3:"2.0";}}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";s:5:"child";a:1:{s:0:"";a:1:{s:7:"channel";a:1:{i:0;a:6:{s:4:"data";s:52:"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\n \n	\n		\n		\n		\n		\n		\n		\n		\n		\n		\n	";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";s:5:"child";a:4:{s:0:"";a:8:{s:5:"title";a:1:{i:0;a:5:{s:4:"data";s:14:"WordPress News";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}s:4:"link";a:1:{i:0;a:5:{s:4:"data";s:26:"https://wordpress.org/news";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}s:11:"description";a:1:{i:0;a:5:{s:4:"data";s:59:"The latest news about WordPress and the WordPress community";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}s:13:"lastBuildDate";a:1:{i:0;a:5:{s:4:"data";s:31:"Mon, 24 Jun 2024 19:10:30 +0000";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}s:8:"language";a:1:{i:0;a:5:{s:4:"data";s:5:"en-US";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}s:9:"generator";a:1:{i:0;a:5:{s:4:"data";s:40:"https://wordpress.org/?v=6.6-beta4-58557";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}s:5:"image";a:1:{i:0;a:6:{s:4:"data";s:11:"\n	\n	\n	\n	\n	\n";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";s:5:"child";a:1:{s:0:"";a:5:{s:3:"url";a:1:{i:0;a:5:{s:4:"data";s:29:"https://s.w.org/favicon.ico?2";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}s:5:"title";a:1:{i:0;a:5:{s:4:"data";s:14:"WordPress News";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}s:4:"link";a:1:{i:0;a:5:{s:4:"data";s:26:"https://wordpress.org/news";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}s:5:"width";a:1:{i:0;a:5:{s:4:"data";s:2:"32";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}s:6:"height";a:1:{i:0;a:5:{s:4:"data";s:2:"32";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}}}}}s:4:"item";a:10:{i:0;a:6:{s:4:"data";s:60:"\n		\n		\n		\n		\n		\n				\n		\n		\n\n					\n										\n					\n		\n		\n			";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";s:5:"child";a:4:{s:0:"";a:6:{s:5:"title";a:1:{i:0;a:5:{s:4:"data";s:15:"WordPress 6.5.5";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}s:4:"link";a:1:{i:0;a:5:{s:4:"data";s:51:"https://wordpress.org/news/2024/06/wordpress-6-5-5/";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}s:7:"pubDate";a:1:{i:0;a:5:{s:4:"data";s:31:"Mon, 24 Jun 2024 19:10:30 +0000";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}s:8:"category";a:2:{i:0;a:5:{s:4:"data";s:8:"Releases";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}i:1;a:5:{s:4:"data";s:8:"Security";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}s:4:"guid";a:1:{i:0;a:5:{s:4:"data";s:35:"https://wordpress.org/news/?p=17426";s:7:"attribs";a:1:{s:0:"";a:1:{s:11:"isPermaLink";s:5:"false";}}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}s:11:"description";a:1:{i:0;a:5:{s:4:"data";s:377:"WordPress 6.5.5 is now available! This release features three security fixes. Because this is a security release, it is recommended that you update your sites immediately. This minor release also includes 3 bug fixes in Core. You can download WordPress 6.5.5 from WordPress.org, or visit your WordPress Dashboard, click “Updates”, and then click “Update Now”. [&#8230;]";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}}s:32:"http://purl.org/dc/elements/1.1/";a:1:{s:7:"creator";a:1:{i:0;a:5:{s:4:"data";s:12:"Aaron Jorbin";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}}s:40:"http://purl.org/rss/1.0/modules/content/";a:1:{s:7:"encoded";a:1:{i:0;a:5:{s:4:"data";s:5127:"\n<h2 class="wp-block-heading">WordPress 6.5.5 is now available!</h2>\n\n\n\n<p>This release features three security fixes. Because this is a security release, <strong>it is recommended that you update your sites immediately. </strong>This minor release also includes <a href="https://core.trac.wordpress.org/query?component=!Build%2FTest+Tools&amp;milestone=6.5.5&amp;col=id&amp;col=summary&amp;col=owner&amp;col=type&amp;col=status&amp;col=priority&amp;col=component&amp;order=priority">3 bug fixes</a> in Core.</p>\n\n\n\n<p>You can <a href="https://wordpress.org/wordpress-6.5.5.zip">download WordPress 6.5.5 from WordPress.org</a>, or visit your WordPress Dashboard, click “Updates”, and then click “Update Now”. If you have sites that support automatic background updates, the update process will begin automatically.</p>\n\n\n\n<p>WordPress 6.5.5 is a short-cycle release. The next major release will be version 6.6 which is scheduled for July 16, 2024.</p>\n\n\n\n<p>For more information on WordPress 6.5.5, please visit the <a href="https://wordpress.org/documentation/wordpress-version/version-6-5-5/">HelpHub site</a>.</p>\n\n\n\n<h2 class="wp-block-heading">Security updates included in this release</h2>\n\n\n\n<p>The security team would like to thank the following people for <a href="https://hackerone.com/wordpress?type=team">responsibly reporting vulnerabilities</a>, and allowing them to be fixed in this release:</p>\n\n\n\n<ul class="wp-block-list">\n<li>A cross-site scripting (XSS) vulnerability affecting the HTML API reported by Dennis Snell of the WordPress Core Team, along with Alex Concha and Grzegorz (Greg) Ziółkowski of the WordPress security team.</li>\n\n\n\n<li>A cross-site scripting (XSS) vulnerability affecting the Template Part block reported independently by Rafie Muhammad of Patchstack and during a third party security audit.</li>\n\n\n\n<li>A path traversal issue affecting sites hosted on Windows reported independently by Rafie M &amp; Edouard L of Patchstack, David Fifield, <a href="https://hackerone.com/x89">x89</a>, <a href="https://hackerone.com/apple502j">apple502j</a>, and <a href="https://hackerone.com/mishre">mishre</a>.</li>\n</ul>\n\n\n\n<h2 class="wp-block-heading">Thank you to these WordPress contributors</h2>\n\n\n\n<p>This release was led by <a href="https://profiles.wordpress.org/jorbin/">Aaron Jorbin</a>.</p>\n\n\n\n<p>WordPress 6.5.5 would not have been possible without the contributions of the following people. Their asynchronous coordination to deliver maintenance and security fixes into a stable release is a testament to the power and capability of the WordPress community.</p>\n\n\n\n<p class="is-style-wporg-props-medium"><a href="https://profiles.wordpress.org/jorbin">Aaron Jorbin</a>, <a href="https://profiles.wordpress.org/xknown">Alex Concha</a>, <a href="https://profiles.wordpress.org/azaozz">Andrew Ozz</a>, <a href="https://profiles.wordpress.org/bernhard-reiter">bernhard-reiter</a>, <a href="https://profiles.wordpress.org/costdev">Colin Stewart</a>, <a href="https://profiles.wordpress.org/davidbaumwald/">David Baumwald</a>, <a href="https://profiles.wordpress.org/dmsnell">Dennis Snell</a>, <a href="https://profiles.wordpress.org/grantmkin">Grant M. Kinney</a>, <a href="https://profiles.wordpress.org/gziolo">Greg Ziółkowski</a>, <a href="https://profiles.wordpress.org/audrasjb">Jb Audras</a>, <a href="https://profiles.wordpress.org/desrosj">Jonathan Desrosiers</a>, <a href="https://profiles.wordpress.org/matveb">Matias Ventura</a>, <a href="https://profiles.wordpress.org/mcsf">Miguel Fonseca</a>, <a href="https://profiles.wordpress.org/peterwilsoncc">Peter Wilson</a>, <a href="https://profiles.wordpress.org/rajinsharwar">Rajin Sharwar</a>, <a href="https://profiles.wordpress.org/coffee2code">Scott Reilly</a>, <a href="https://profiles.wordpress.org/hellofromTonya">Tonya Mork</a></p>\n\n\n\n<h2 class="wp-block-heading">How to contribute</h2>\n\n\n\n<p>To get involved in WordPress core development, head over to Trac, <a href="https://core.trac.wordpress.org/report/6">pick a ticket</a>, and join the conversation in the <a href="https://wordpress.slack.com/archives/C02RQBWTW">#core</a> Slack channel. Need help? Check out the <a href="https://make.wordpress.org/core/handbook/tutorials/faq-for-new-contributors/">Core Contributor Handbook</a>.</p>\n\n\n\n<p><em>Already testing WordPress 6.6? The fourth beta is now available (<a href="https://wordpress.org/wordpress-6.6-beta4.zip">zip</a>) and it contains these security fixes. For more on 6.6, see the <a href="https://wordpress.org/news/2024/06/wordpress-6-6-beta-3/">beta 3 announcement post</a>. Learn more about <a href="https://make.wordpress.org/test/2024/06/03/help-test-wordpress-6-6/">testing WordPress 6.6 here</a>.</em></p>\n\n\n\n<p>Props to <a href="https://profiles.wordpress.org/paulkevan/">Paul Kevan</a>, <a href="https://profiles.wordpress.org/ehtis/">Ehtisham Siddiqui</a>, <a href="https://profiles.wordpress.org/xknown/">Alex Concha</a>, <a href="https://profiles.wordpress.org/hellofromTonya">Tonya Mork</a>, and <a href="https://profiles.wordpress.org/angelasjin/">Angela Jin</a> for reviewing.</p>\n";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}}s:30:"com-wordpress:feed-additions:1";a:1:{s:7:"post-id";a:1:{i:0;a:5:{s:4:"data";s:5:"17426";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}}}}i:1;a:6:{s:4:"data";s:61:"\n		\n		\n		\n		\n		\n				\n		\n		\n\n					\n										\n					\n		\n		\n\n			";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";s:5:"child";a:4:{s:0:"";a:7:{s:5:"title";a:1:{i:0;a:5:{s:4:"data";s:43:"WP Briefing: Episode 82: WCEU Hallway Track";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}s:4:"link";a:1:{i:0;a:5:{s:4:"data";s:65:"https://wordpress.org/news/2024/06/episode-82-wceu-hallway-track/";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}s:7:"pubDate";a:1:{i:0;a:5:{s:4:"data";s:31:"Mon, 24 Jun 2024 12:00:00 +0000";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}s:8:"category";a:2:{i:0;a:5:{s:4:"data";s:7:"Podcast";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}i:1;a:5:{s:4:"data";s:11:"wp-briefing";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}s:4:"guid";a:1:{i:0;a:5:{s:4:"data";s:53:"https://wordpress.org/news/?post_type=podcast&p=17409";s:7:"attribs";a:1:{s:0:"";a:1:{s:11:"isPermaLink";s:5:"false";}}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}s:11:"description";a:1:{i:0;a:5:{s:4:"data";s:312:"Big events create big moments, and WordCamp Europe 2024 was no exception. Join host Josepha Haden Chomphosy on this episode of the WordPress Briefing as she shares her top insights  and favorite highlights from the event. Discover what the WordPress community focused on during this exciting three-day gathering.";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}s:9:"enclosure";a:1:{i:0;a:5:{s:4:"data";s:0:"";s:7:"attribs";a:1:{s:0:"";a:3:{s:3:"url";s:51:"https://wordpress.org/news/files/2024/06/WPB082.mp3";s:6:"length";s:1:"0";s:4:"type";s:0:"";}}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}}s:32:"http://purl.org/dc/elements/1.1/";a:1:{s:7:"creator";a:1:{i:0;a:5:{s:4:"data";s:14:"Brett McSherry";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}}s:40:"http://purl.org/rss/1.0/modules/content/";a:1:{s:7:"encoded";a:1:{i:0;a:5:{s:4:"data";s:10086:"\n<p>Big events create big moments, and WordCamp Europe 2024 was no exception. Join host Josepha Haden Chomphosy on this episode of the WordPress Briefing as she shares her top insights  and favorite highlights from the event. Discover what the WordPress community focused on during this exciting three-day gathering.</p>\n\n\n\n<h2 class="wp-block-heading">Credits</h2>\n\n\n\n<p>Host:&nbsp;<a href="https://profiles.wordpress.org/chanthaboune/">Josepha Haden Chomphosy</a><br>Editor:&nbsp;<a href="https://profiles.wordpress.org/dustinhartzler/">Dustin Hartzler</a><br>Logo:&nbsp;<a href="https://profiles.wordpress.org/javiarce/">Javier Arce</a><br>Production:&nbsp;<a href="https://profiles.wordpress.org/bjmcsherry/">Brett McSherry</a><br>Song: Fearless First by Kevin MacLeod</p>\n\n\n\n<h2 class="wp-block-heading">Show Notes</h2>\n\n\n\n<ul class="wp-block-list">\n<li><a href="https://europe.wordcamp.org/">WordCamp Europe</a></li>\n\n\n\n<li><strong>Small List of Big Things</strong>\n<ul class="wp-block-list">\n<li><a href="https://make.wordpress.org/core/6-6/">WordPress 6.6 RC1 (and upcoming schedule)</a></li>\n\n\n\n<li><a href="https://make.wordpress.org/project/2024/05/31/wordpress-project-contributor-handbook-v2/">WordPress Project Contributor Handbook v2</a></li>\n\n\n\n<li><a href="https://make.wordpress.org/sustainability/2024/06/12/the-sustainability-teams-handbook-for-events-is-here/">The Sustainability Team’s Handbook for Events&nbsp;is here!</a></li>\n\n\n\n<li><a href="https://us.wordcamp.org/2024/volunteering-at-wordcamp-us-2024/">Volunteering at WordCamp US 2024</a>&nbsp;</li>\n</ul>\n</li>\n\n\n\n<li>Have a question you’d like answered? Submit them to&nbsp;<a href="mailto:wpbriefing@WordPress.org">WPBriefing@WordPress.org</a>.</li>\n</ul>\n\n\n\n<h2 class="wp-block-heading">Transcript</h2>\n\n\n\n<p>[00:00:00]&nbsp;<strong>Josepha:</strong>&nbsp;Hello, everyone, and welcome to the WordPress Briefing, the podcast where you can catch quick explanations of the ideas behind the WordPress open source project, some insight into the community that supports it, and get a small list of big things coming up in the next two weeks. I’m your host, Josepha Haden Chomphosy. Here we go.</p>\n\n\n\n<p>[00:00:28] (Intro music)&nbsp;</p>\n\n\n\n<p>[00:00:40]&nbsp;<strong>Josepha:</strong> My friends, another WordCamp Europe is in the books. We had the second-highest number of tickets sold in the history of our event series, with the first being WordCamp Europe in Berlin. But even with that number of tickets sold, that number of people gathering together to talk about WordPress and related things, there were still a lot of people who didn&#8217;t get to join us.</p>\n\n\n\n<p>[00:01:01] <strong>Josepha:</strong> For some, that came with experiencing FOMO, but some of you embraced the JOMO of it all. Either way, at this point, there are a good collection of wrap-ups and round-ups going around, so I&#8217;m here to tell you a bit about what was buzzing in the hallway track.&nbsp;</p>\n\n\n\n<p>Firstly, everyone was so excited to see old friends and make new ones. Everywhere I turned, I saw WordPressers in clusters catching up, most included new to the crew faces. So we know that we were using the Pac-Man rule that we love so much. But even while they were catching up on the last two, three, four years, they were also talking to each other about how to get more folks to things like this. </p>\n\n\n\n<p>Since we all generally agree that your first time meeting other WordPressers can be a truly pivotal moment in your WordPress journey, it was a delight to hear so much brainstorming focused on that. From mentorship to community introduction and the future of our events, the question of how to keep our ecosystem healthy and thriving was a big topic. Does any one of us have all the answers to this? No, but fortunately, we&#8217;ve got a global set of thinkers working on this global question. So, together, I&#8217;m sure we can come up with some good guesses to try out.</p>\n\n\n\n<p>[00:02:21] <strong>Josepha:</strong> Secondly, I saw a ton of talks and discussions about career development, not only about how to learn more but also how to be a champion for open source in your company, how to advocate for contribution as a best business practice. And what other communities can teach us about how they commit to their user&#8217;s continuing education, for lack of a friendlier term.</p>\n\n\n\n<p>And boy, do I love a good conversation about how to make working in open source easier, make it more meaningful, and more impactful. I&#8217;m in favor of anything that helps to dignify our profession. The front-facing, easy-to-use experience of WordPress, in particular, has been misunderstood to mean that we are a simple piece of software for simple tasks. And that is the way with our mission really. If we succeed at democratizing publishing or learning or commerce for that matter, we are taking the arcane and making it mundane. But simple to use doesn&#8217;t mean simple to create. And I want all of our future employers and clients to see that.</p>\n\n\n\n<p>[00:03:24] <strong>Josepha:</strong> And then the final thing that I saw lighting up the hallway track was the idea of bringing life and excitement back to the web. WordPress has been fighting against closed systems for a long time, but as Matt alluded to in his keynote, merely having an open web is still not quite as fun as having an active and dynamic one. And we saw that both in general desire to bring fun back to being online, but also in the fresh variety of demos and workshops that we saw in the fun that was brought to the event. There were new and shocking implementations of Playground, I must say. Which, as far as I can tell, will basically be able to run everything one day.</p>\n\n\n\n<p>[00:04:03] <strong>Josepha:</strong> But at WordCamp Europe, it ran; it powered our second massive hybrid translation event, where we translated something like 50,000 strings. We also had an amazing speed-building duel with an accepted future challenge between Jessica Lyschik and Matt Mullenweg. And not for nothing; the way we designed; the way the event area was put together included ways to stop and just have fun.</p>\n\n\n\n<p>There was a little grassy area with yard games and smaller pods of chairs for those quick hallway catch-ups that you just don&#8217;t get anywhere else. And for me, it was simply lovely to see everyone embracing the fun that was there, but also hearing about how much they wanted to help the web embrace the fun that could be.</p>\n\n\n\n<p>[00:04:48] (Music interlude)&nbsp;</p>\n\n\n\n<p>[00:04:55] <strong>Josepha:</strong> Thanks for listening to my hallway track recap. Hopefully, it caused JOMO, not FOMO. And now, let&#8217;s turn our attention to the small list of big things.</p>\n\n\n\n<p>[00:05:05] <strong>Josepha:</strong> First thing on my list is WordPress 6.6 update. So we are reaching the release candidate phase tomorrow. WordPress 6.6 RC1 will be released, so download and join the community helping us to get this release out the door. It is scheduled for July 16th. If you have plugins or themes or any sort of business that uses WordPress, now is the time to get in and test it on a test site. I don&#8217;t recommend putting it in production at any point, but come and test it. Help us break it so that we can make sure that it doesn&#8217;t break for other people, for the, you know, 43% of the web that uses it when we get it out the door on the 16th.&nbsp;</p>\n\n\n\n<p>The second thing on the list is that we have a WordPress Project Contributor Handbook V2 out there. It aims to be the quintessential resource for everyone in our community. And it will provide a bird&#8217;s eye view of where to find key information and different aspects of our community. How it all kind of connects together. And, just like a release, we really need some feedback from you. There is the repo on GitHub where you can go and kind of make inline comments, join the discussion about it. It can be a go-to resource if we look at it together and make sure that it has as much information as clearly stated as you wished you had when you were learning your way around WordPress for the first time.&nbsp;</p>\n\n\n\n<p>[00:06:27] <strong>Josepha:</strong> The third thing on the list is actually another handbook. So, the Sustainability Team has put together a handbook specifically for events. It&#8217;s their first version, and over the past few months, members of that team have been sharing their ideas and experiences on how WordPress community events can be held more sustainably. All this input created a first draft, which eventually became this first version. And so we&#8217;ll put a link in the show notes, wander over there, take a look at it, see what some best practices for sustainable events are in the WordPress ecosystem.&nbsp;</p>\n\n\n\n<p>[00:07:02] <strong>Josepha:</strong> And then the final thing on my list is about WordCamp US. I realize this is a podcast about WordCamp Europe right now. And so it&#8217;s odd to think that I&#8217;m moving right along into WordCamp US. However, there is a deadline coming up. July 1st is the last day to sign up to be a volunteer at this event. It&#8217;s taking place this year in Portland, Oregon, on the west side of the US. And it should be a really fun time. It&#8217;s middle of September. Come on out there. Learn about WordPress. Learn about contribution. Maybe get some voodoo donuts. You know, the important things.&nbsp;</p>\n\n\n\n<p>And that, my friends, is your small list of big things. Don&#8217;t forget to follow us on your favorite podcast app or subscribe directly on WordPress.org/news. You&#8217;ll get a friendly reminder whenever there&#8217;s a new episode. If you liked what you heard today, share it with a fellow WordPresser. Or, if you had questions about what you heard, you can share those with me at WPBriefing@WordPress.org. I am your host, Josepha Haden Chomphosy. Thanks for tuning in today for the WordPress Briefing, and I&#8217;ll see you again in a couple of weeks.&nbsp;</p>\n\n\n\n<p>[00:08:06] (Music outro)&nbsp;</p>\n";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}}s:30:"com-wordpress:feed-additions:1";a:1:{s:7:"post-id";a:1:{i:0;a:5:{s:4:"data";s:5:"17409";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}}}}i:2;a:6:{s:4:"data";s:63:"\n		\n		\n		\n		\n		\n				\n		\n		\n		\n\n					\n										\n					\n		\n		\n			";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";s:5:"child";a:4:{s:0:"";a:6:{s:5:"title";a:1:{i:0;a:5:{s:4:"data";s:20:"WordPress 6.6 Beta 3";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}s:4:"link";a:1:{i:0;a:5:{s:4:"data";s:56:"https://wordpress.org/news/2024/06/wordpress-6-6-beta-3/";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}s:7:"pubDate";a:1:{i:0;a:5:{s:4:"data";s:31:"Tue, 18 Jun 2024 16:37:33 +0000";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}s:8:"category";a:3:{i:0;a:5:{s:4:"data";s:11:"Development";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}i:1;a:5:{s:4:"data";s:8:"Releases";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}i:2;a:5:{s:4:"data";s:8:"releases";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}s:4:"guid";a:1:{i:0;a:5:{s:4:"data";s:35:"https://wordpress.org/news/?p=17392";s:7:"attribs";a:1:{s:0:"";a:1:{s:11:"isPermaLink";s:5:"false";}}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}s:11:"description";a:1:{i:0;a:5:{s:4:"data";s:342:"WordPress 6.6 Beta 3 is here! Please download and test it. This beta version of the WordPress software is under development. Please do not install, run, or test this version of WordPress on production or mission-critical websites—you risk unexpected results if you do. Instead, test Beta 3 on a local site or a testing environment [&#8230;]";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}}s:32:"http://purl.org/dc/elements/1.1/";a:1:{s:7:"creator";a:1:{i:0;a:5:{s:4:"data";s:8:"marybaum";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}}s:40:"http://purl.org/rss/1.0/modules/content/";a:1:{s:7:"encoded";a:1:{i:0;a:5:{s:4:"data";s:7996:"\n<p><br>WordPress 6.6 Beta 3 is here! Please download and test it.</p>\n\n\n\n<p id="block-79834dd4-c99a-477a-b722-091806a32976"><strong>This beta version of the WordPress software is under development. </strong>Please do not install, run, or test this version of WordPress on production or mission-critical websites—you risk unexpected results if you do.</p>\n\n\n\n<p id="block-aa4b335e-b1a2-4904-a68c-c3e73e574386">Instead, test Beta 3 on a local site or a testing environment in any of these four ways:</p>\n\n\n\n<figure class="wp-block-table"><table class="has-fixed-layout"><tbody><tr><th>Plugin</th><td>Install and activate the <a href="https://wordpress.org/plugins/wordpress-beta-tester/">WordPress Beta Tester</a> plugin on a WordPress install. (Select the “Bleeding edge” channel and “Beta/RC Only” stream).</td></tr><tr><th>Direct Download</th><td>Download the <a href="https://wordpress.org/wordpress-6.6-beta3.zip">Beta 3 version (zip)</a> and install it on a WordPress website.</td></tr><tr><th>Command Line</th><td>Use this <a href="https://make.wordpress.org/cli/">WP-CLI</a> command:<br><code>wp core update --version=6.6-beta3</code></td></tr><tr><th>WordPress Playground</th><td>Use a <a href="https://playground.wordpress.net/#{%20%22preferredVersions%22:%20{%20%22php%22:%20%228.0%22,%20%22wp%22:%20%22beta%22%20},%20%22features%22:%20{%20%22networking%22:%20true%20},%20%22steps%22:%20[%20{%20%22step%22:%20%22login%22,%20%22username%22:%20%22admin%22,%20%22password%22:%20%22password%22%20},%20{%20%22step%22:%20%22importFile%22,%20%22file%22:%20{%20%22resource%22:%20%22url%22,%20%22url%22:%20%22https://raw.githubusercontent.com/wpaccessibility/a11y-theme-unit-test/master/a11y-theme-unit-test-data.xml%22%20}%20},%20{%20%22step%22:%20%22importFile%22,%20%22file%22:%20{%20%22resource%22:%20%22url%22,%20%22url%22:%20%22https://raw.githubusercontent.com/WordPress/theme-test-data/master/themeunittestdata.wordpress.xml%22%20}%20},%20{%20%22step%22:%20%22installPlugin%22,%20%22pluginZipFile%22:%20{%20%22resource%22:%20%22wordpress.org/plugins%22,%20%22slug%22:%20%22query-monitor%22%20},%20%22options%22:%20{%20%22activate%22:%20false%20},%20%22progress%22:%20{%20%22weight%22:%202%20}%20},%20{%20%22step%22:%20%22installPlugin%22,%20%22pluginZipFile%22:%20{%20%22resource%22:%20%22wordpress.org/plugins%22,%20%22slug%22:%20%22create-block-theme%22%20},%20%22progress%22:%20{%20%22weight%22:%202%20}%20},%20{%20%22step%22:%20%22installPlugin%22,%20%22pluginZipFile%22:%20{%20%22resource%22:%20%22wordpress.org/plugins%22,%20%22slug%22:%20%22debug-bar%22%20},%20%22progress%22:%20{%20%22weight%22:%202%20}%20},%20{%20%22step%22:%20%22installPlugin%22,%20%22pluginZipFile%22:%20{%20%22resource%22:%20%22wordpress.org/plugins%22,%20%22slug%22:%20%22health-check%22%20},%20%22progress%22:%20{%20%22weight%22:%202%20}%20},%20{%20%22step%22:%20%22installPlugin%22,%20%22pluginZipFile%22:%20{%20%22resource%22:%20%22wordpress.org/plugins%22,%20%22slug%22:%20%22test-reports%22%20},%20%22progress%22:%20{%20%22weight%22:%202%20}%20},%20{%20%22step%22:%20%22installPlugin%22,%20%22pluginZipFile%22:%20{%20%22resource%22:%20%22wordpress.org/plugins%22,%20%22slug%22:%20%22user-switching%22%20},%20%22progress%22:%20{%20%22weight%22:%202%20}%20}%20]%20}">6.6 Beta 3 WordPress Playground instance</a> to test the software directly in your browser. This might be the easiest way ever—no separate sites, no setup. Just click and go! </td></tr></tbody></table><figcaption class="wp-element-caption">Four ways to test WordPress Beta 3.</figcaption></figure>\n\n\n\n<p id="block-7e6a92e6-dba7-4f69-9226-f4dcab4a0b91">The target release date for WordPress 6.6 is <strong>July 16, 2024</strong>. Your help testing Beta and RC versions over the next four weeks is vital to making sure the final release is everything it should be: stable, powerful, and intuitive.</p>\n\n\n\n<h2 class="wp-block-heading" id="block-aebce12b-08f8-40a7-9fe6-5a08f75d2254">If you find an issue</h2>\n\n\n\n<p id="block-b9e58289-f6cb-4bdd-85a1-eb8d9a704ae4">If you run into an issue, please share it in the&nbsp;<a href="https://wordpress.org/support/forum/alphabeta/">Alpha/Beta area</a>&nbsp;of the support forums. If you are comfortable submitting a reproducible bug report, you can do so&nbsp;<a href="https://core.trac.wordpress.org/newticket">via WordPress Trac</a>. You can also check your issue against a list of&nbsp;<a href="https://core.trac.wordpress.org/tickets/major">known bugs</a>.</p>\n\n\n\n<h2 class="wp-block-heading">The bug bounty doubles in the beta period</h2>\n\n\n\n<p>The WordPress community sponsors a&nbsp;<a href="https://make.wordpress.org/security/2024/06/04/wordpress-6-6-is-coming/">financial reward for reporting new, unreleased security vulnerabilities.</a>&nbsp;That reward doubles between Beta 1, which landed June 4, and the final Release Candidate (RC), which will happen July 9. Please follow the project’s responsible-disclosure practices detailed on this&nbsp;<a href="https://hackerone.com/wordpress">HackerOne page</a>&nbsp;and in this&nbsp;<a href="https://wordpress.org/about/security/">security white paper</a>.</p>\n\n\n\n<h2 class="wp-block-heading">The work continues</h2>\n\n\n\n<p><strong>Catch up with what&#8217;s new in 6.6:</strong> <a href="https://wordpress.org/news/2024/06/wordpress-6-6-beta-1/" data-type="post" data-id="17289">check out the Beta 1 announcement for the highlights.</a></p>\n\n\n\n<p>Beta 3 packs in more than 50 updates to the Editor since the Beta 2 release, including 39 <a href="https://core.trac.wordpress.org/query?status=closed&amp;changetime=06%2F11%2F2024..06%2F16%2[…]id&amp;col=milestone&amp;col=owner&amp;col=type&amp;col=priority&amp;order=id">tickets for WordPress core</a>:</p>\n\n\n\n<ul class="wp-block-list">\n<li><a href="https://github.com/WordPress/gutenberg/commits/trunk?since=2024-06-08&amp;until=2024-06-16" data-type="link" data-id="https://github.com/WordPress/gutenberg/commits/wp/6.5?since=2024-02-14&amp;until=2024-02-20">GitHub commits for 6.6</a> since June 11</li>\n\n\n\n<li><a href="https://core.trac.wordpress.org/query?changetime=06%2F11%2F2024..06%2F16%2F2024&amp;resolution=fixed&amp;milestone=6.6&amp;max=1000&amp;col=id&amp;col=summary&amp;col=milestone&amp;col=owner&amp;col=type&amp;col=status&amp;col=priority&amp;order=milestone">Closed Trac tickets</a> since June 11</li>\n</ul>\n\n\n\n<p>The beta cycle is all about fixing the bugs you find in testing. </p>\n\n\n\n<p><strong>Do you build themes?</strong>&nbsp;Feedback from testing has already prompted a change in the way you offer style variations to your users.</p>\n\n\n\n<p>In Beta 1, if you made preset style variations for your theme, it automatically generated a full set of color-only and type-only options your users could mix and match across the different variations.</p>\n\n\n\n<p><a href="https://github.com/WordPress/gutenberg/pull/62469/commits/83f62ca81ff89b9d395863f6e9b7e82cec76d1b3">In Beta 3, your theme no longer generates those options automatically—you do.</a> So you can present a simpler set of choices, curated to guide users&#8217; efforts to more pleasing results.&nbsp;<a href="https://github.com/WordPress/gutenberg/issues/62285" target="_blank" rel="noreferrer noopener">For more insight into the rationale, see this discussion.</a></p>\n\n\n\n<p>Thanks again for this all-important contribution to WordPress!</p>\n\n\n\n<p class="has-text-align-right is-style-default"><em>Props to <a href=\'https://profiles.wordpress.org/meher/\' class=\'mention\'><span class=\'mentions-prefix\'>@</span>meher</a>,  <a href=\'https://profiles.wordpress.org/rmartinezduque/\' class=\'mention\'><span class=\'mentions-prefix\'>@</span>rmartinezduque</a></em>,  @<em>atachibana</em>,<em> and  <a href=\'https://profiles.wordpress.org/mobarak/\' class=\'mention\'><span class=\'mentions-prefix\'>@</span>mobarak</a> for collaboration and review.</em></p>\n\n\n\n<h2 class="wp-block-heading">A Beta 3 haiku</h2>\n\n\n\n<p>Beta ends at 3<br>One more week, then comes RC<br>When we freeze the strings!</p>\n";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}}s:30:"com-wordpress:feed-additions:1";a:1:{s:7:"post-id";a:1:{i:0;a:5:{s:4:"data";s:5:"17392";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}}}}i:3;a:6:{s:4:"data";s:60:"\n		\n		\n		\n		\n		\n				\n		\n		\n\n					\n										\n					\n		\n		\n			";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";s:5:"child";a:4:{s:0:"";a:6:{s:5:"title";a:1:{i:0;a:5:{s:4:"data";s:36:"Highlights from WordCamp Europe 2024";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}s:4:"link";a:1:{i:0;a:5:{s:4:"data";s:72:"https://wordpress.org/news/2024/06/highlights-from-wordcamp-europe-2024/";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}s:7:"pubDate";a:1:{i:0;a:5:{s:4:"data";s:31:"Sat, 15 Jun 2024 21:29:42 +0000";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}s:8:"category";a:2:{i:0;a:5:{s:4:"data";s:6:"Events";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}i:1;a:5:{s:4:"data";s:4:"WCEU";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}s:4:"guid";a:1:{i:0;a:5:{s:4:"data";s:35:"https://wordpress.org/news/?p=17374";s:7:"attribs";a:1:{s:0:"";a:1:{s:11:"isPermaLink";s:5:"false";}}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}s:11:"description";a:1:{i:0;a:5:{s:4:"data";s:332:"From June 13-15, 2024, WordPress enthusiasts from across the globe gathered in Torino to explore and celebrate the world’s most popular web platform at WordCamp Europe 2024. A dedicated team of 250 volunteers, led by WordCamp veterans Wendie Huis in ‘t Veld, Juan Hernando, and Takis Bouyouris, organized and produced the event.";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}}s:32:"http://purl.org/dc/elements/1.1/";a:1:{s:7:"creator";a:1:{i:0;a:5:{s:4:"data";s:11:"Dan Soschin";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}}s:40:"http://purl.org/rss/1.0/modules/content/";a:1:{s:7:"encoded";a:1:{i:0;a:5:{s:4:"data";s:13904:"\n<p><em>2,584 attendees participated in the 12th annual WordPress event in Europe, held at the </em><a href="https://europe.wordcamp.org/2024/venue/"><em>Lingotto Conference and Exhibition Centre</em></a><em> in Torino, Italy.</em></p>\n\n\n\n<figure class="wp-block-image size-large"><img fetchpriority="high" decoding="async" width="1024" height="683" src="https://i0.wp.com/wordpress.org/news/files/2024/06/wceu-torino-night.jpg?resize=1024%2C683&#038;ssl=1" alt="" class="wp-image-17376" srcset="https://i0.wp.com/wordpress.org/news/files/2024/06/wceu-torino-night.jpg?resize=1024%2C683&amp;ssl=1 1024w, https://i0.wp.com/wordpress.org/news/files/2024/06/wceu-torino-night.jpg?resize=300%2C200&amp;ssl=1 300w, https://i0.wp.com/wordpress.org/news/files/2024/06/wceu-torino-night.jpg?resize=768%2C512&amp;ssl=1 768w, https://i0.wp.com/wordpress.org/news/files/2024/06/wceu-torino-night.jpg?w=1080&amp;ssl=1 1080w" sizes="(max-width: 1000px) 100vw, 1000px" data-recalc-dims="1" /><figcaption class="wp-element-caption">The <a href="https://www.museocinema.it/en/museum-and-ma-prolo-foundation/mole-antonelliana">Mole Antonelliana</a> in Torino, illuminated to celebrate WordCamp Europe 2024</figcaption></figure>\n\n\n\n<p>From June 13-15, 2024, WordPress enthusiasts from across the globe gathered in Torino to explore and celebrate the world’s most popular web platform. A dedicated team of 250 volunteers, led by WordCamp veterans Wendie Huis in ‘t Veld, Juan Hernando, and Takis Bouyouris, organized and produced the event.</p>\n\n\n\n<h2 class="wp-block-heading">Impact in Action on Contributor Day</h2>\n\n\n\n<p><a href="https://europe.wordcamp.org/2024/contributor-day/">Contributor Day</a> brought together 726 contributors working across 25 teams to support the WordPress project. Their accomplishments included translating 79,059 “strings” for the WordPress user interface across 29 languages, updating documentation for the forthcoming 6.6 release, onboarding new contributors for the support forums and testing teams, and identifying ways to improve plugin security.</p>\n\n\n\n<figure class="wp-block-image size-large"><img decoding="async" width="1024" height="683" src="https://i0.wp.com/wordpress.org/news/files/2024/06/Contributors-at-work.jpeg?resize=1024%2C683&#038;ssl=1" alt="" class="wp-image-17377" srcset="https://i0.wp.com/wordpress.org/news/files/2024/06/Contributors-at-work-scaled.jpeg?resize=1024%2C683&amp;ssl=1 1024w, https://i0.wp.com/wordpress.org/news/files/2024/06/Contributors-at-work-scaled.jpeg?resize=300%2C200&amp;ssl=1 300w, https://i0.wp.com/wordpress.org/news/files/2024/06/Contributors-at-work-scaled.jpeg?resize=768%2C512&amp;ssl=1 768w, https://i0.wp.com/wordpress.org/news/files/2024/06/Contributors-at-work-scaled.jpeg?resize=1536%2C1024&amp;ssl=1 1536w, https://i0.wp.com/wordpress.org/news/files/2024/06/Contributors-at-work-scaled.jpeg?resize=2048%2C1365&amp;ssl=1 2048w" sizes="(max-width: 1000px) 100vw, 1000px" data-recalc-dims="1" /><figcaption class="wp-element-caption">Contributors gathering during WCEU 2024 Contributor Day</figcaption></figure>\n\n\n\n<h2 class="wp-block-heading">Sustainable open source is the future</h2>\n\n\n\n<figure class="wp-block-image size-large"><img decoding="async" width="1024" height="576" src="https://i0.wp.com/wordpress.org/news/files/2024/06/day1-keynote.jpg?resize=1024%2C576&#038;ssl=1" alt="" class="wp-image-17378" srcset="https://i0.wp.com/wordpress.org/news/files/2024/06/day1-keynote.jpg?resize=1024%2C576&amp;ssl=1 1024w, https://i0.wp.com/wordpress.org/news/files/2024/06/day1-keynote.jpg?resize=300%2C169&amp;ssl=1 300w, https://i0.wp.com/wordpress.org/news/files/2024/06/day1-keynote.jpg?resize=768%2C432&amp;ssl=1 768w, https://i0.wp.com/wordpress.org/news/files/2024/06/day1-keynote.jpg?resize=1536%2C864&amp;ssl=1 1536w, https://i0.wp.com/wordpress.org/news/files/2024/06/day1-keynote.jpg?w=1920&amp;ssl=1 1920w" sizes="(max-width: 1000px) 100vw, 1000px" data-recalc-dims="1" /><figcaption class="wp-element-caption">Keynote presenters, Joost de Valk and Juliette Reinders Folmer</figcaption></figure>\n\n\n\n<p>Joost de Valk and Juliette Reinders Folmer delivered the event&#8217;s opening keynote address on <a href="https://europe.wordcamp.org/2024/session/sustainable-open-source-is-the-future/">sustaining open source software projects</a>. Their keynote covered funding open source, contributing beyond code, and convincing buyers in commercial enterprises that open source is a viable alternative to proprietary platforms.</p>\n\n\n\n<h2 class="wp-block-heading">Two days of engaging sessions</h2>\n\n\n\n<p>Friday and Saturday saw 60 presentations and workshops held across <a href="https://europe.wordcamp.org/2024/schedule/">three tracks</a>. Topics included WordPress development, accessibility, design, business, community, artificial intelligence, and cybersecurity.</p>\n\n\n\n<div class="wp-block-columns is-layout-flex wp-container-core-columns-is-layout-1 wp-block-columns-is-layout-flex">\n<div class="wp-block-column is-layout-flow wp-block-column-is-layout-flow">\n<figure class="wp-block-image size-large"><img loading="lazy" decoding="async" width="1024" height="683" src="https://i0.wp.com/wordpress.org/news/files/2024/06/session-photo2-1.jpg?resize=1024%2C683&#038;ssl=1" alt="" class="wp-image-17381" srcset="https://i0.wp.com/wordpress.org/news/files/2024/06/session-photo2-1-scaled.jpg?resize=1024%2C683&amp;ssl=1 1024w, https://i0.wp.com/wordpress.org/news/files/2024/06/session-photo2-1-scaled.jpg?resize=300%2C200&amp;ssl=1 300w, https://i0.wp.com/wordpress.org/news/files/2024/06/session-photo2-1-scaled.jpg?resize=768%2C512&amp;ssl=1 768w, https://i0.wp.com/wordpress.org/news/files/2024/06/session-photo2-1-scaled.jpg?resize=1536%2C1024&amp;ssl=1 1536w, https://i0.wp.com/wordpress.org/news/files/2024/06/session-photo2-1-scaled.jpg?resize=2048%2C1365&amp;ssl=1 2048w" sizes="(max-width: 1000px) 100vw, 1000px" data-recalc-dims="1" /><figcaption class="wp-element-caption">Speed Build Session</figcaption></figure>\n</div>\n\n\n\n<div class="wp-block-column is-layout-flow wp-block-column-is-layout-flow">\n<figure class="wp-block-image size-large is-resized"><img loading="lazy" decoding="async" width="1024" height="783" src="https://i0.wp.com/wordpress.org/news/files/2024/06/session-photo1-1.jpg?resize=1024%2C783&#038;ssl=1" alt="" class="wp-image-17382" style="width:285px;height:auto" srcset="https://i0.wp.com/wordpress.org/news/files/2024/06/session-photo1-1.jpg?resize=1024%2C783&amp;ssl=1 1024w, https://i0.wp.com/wordpress.org/news/files/2024/06/session-photo1-1.jpg?resize=300%2C229&amp;ssl=1 300w, https://i0.wp.com/wordpress.org/news/files/2024/06/session-photo1-1.jpg?resize=768%2C587&amp;ssl=1 768w, https://i0.wp.com/wordpress.org/news/files/2024/06/session-photo1-1.jpg?w=1404&amp;ssl=1 1404w" sizes="(max-width: 1000px) 100vw, 1000px" data-recalc-dims="1" /><figcaption class="wp-element-caption">Connect Series</figcaption></figure>\n</div>\n</div>\n\n\n\n<p>A youth workshop gave younger attendees hands-on opportunities to build WordPress websites, explore new tech, and learn about internet safety. Meanwhile, a wellness-themed track included yoga lessons and walking tours of Torino, encouraging attendees to step away from their screens and explore the beauty of this year’s host city.</p>\n\n\n\n<h2 class="wp-block-heading">Mid-year project update</h2>\n\n\n\n<p>WordPress Cofounder Matt Mullenweg shared a <a href="https://youtu.be/ELW4Jdvujbc">mid-year project update on WordPress</a> and concluded by fielding questions from the audience on various topics, from Gutenberg Phases to the WordPress Playground, and acknowledging a request to escalate a bug fix.</p>\n\n\n\n<p>Matt’s presentation highlighted the success of the <a href="https://make.wordpress.org/community/2024/06/15/wordpress-contributor-mentorship-program-q4-2024-call-for-interest/">contributor mentorship program</a> and WCEU Contributor Day, demoed Translate Live, and shared an update on the <a href="https://wordpress.org/data-liberation/">Data Liberation</a> initiative.&nbsp;</p>\n\n\n\n<p>Matt also covered the latest innovations with <a href="https://wordpress.org/playground/">WordPress Playground</a>, highlighted <a href="https://wordpress.org/news/2024/04/how-wordpress-is-creating-a-faster-web/">performance gains</a>, and previewed features anticipated in future releases, like rollbacks for auto-updates and zoomed-out view.</p>\n\n\n\n<figure class="wp-block-image size-large"><img loading="lazy" decoding="async" width="1024" height="683" src="https://i0.wp.com/wordpress.org/news/files/2024/06/matt.jpg?resize=1024%2C683&#038;ssl=1" alt="" class="wp-image-17383" srcset="https://i0.wp.com/wordpress.org/news/files/2024/06/matt-scaled.jpg?resize=1024%2C683&amp;ssl=1 1024w, https://i0.wp.com/wordpress.org/news/files/2024/06/matt-scaled.jpg?resize=300%2C200&amp;ssl=1 300w, https://i0.wp.com/wordpress.org/news/files/2024/06/matt-scaled.jpg?resize=768%2C512&amp;ssl=1 768w, https://i0.wp.com/wordpress.org/news/files/2024/06/matt-scaled.jpg?resize=1536%2C1024&amp;ssl=1 1536w, https://i0.wp.com/wordpress.org/news/files/2024/06/matt-scaled.jpg?resize=2048%2C1365&amp;ssl=1 2048w" sizes="(max-width: 1000px) 100vw, 1000px" data-recalc-dims="1" /><figcaption class="wp-element-caption">WordPress Cofounder Matt Mullenweg</figcaption></figure>\n\n\n\n<p>Acknowledging an exciting new trend in the WordPress community, Mullenweg discussed “speed build challenges,” where onlookers watch WordPress experts build websites in real-time, showcasing tips, shortcuts, and best practices. One such event took place during a WCEU session, and in the Q&amp;A portion of Matt’s presentation, he was invited to participate in one–an invitation he accepted!</p>\n\n\n\n<p>Matt reflected on WordPress reaching its 21st anniversary since he and Mike Little launched the first version in 2003. He <a href="https://ma.tt/2024/05/wp21/">shared 11 things</a> to ensure that WordPress remains sustainable for decades to come:</p>\n\n\n\n<ol class="wp-block-list">\n<li>Simple things should be easy and intuitive, and complex things possible.</li>\n\n\n\n<li>Blogs and dynamic sites are better.</li>\n\n\n\n<li>Documentation should be wiki-easy to edit.</li>\n\n\n\n<li>Forums should be front and center.</li>\n\n\n\n<li>Plugins and themes with community infrastructure.</li>\n\n\n\n<li>Great theme previews and diverse aesthetics.</li>\n\n\n\n<li>We can’t over-index for guidelines and requirements.</li>\n\n\n\n<li>Feedback loops are so important.</li>\n\n\n\n<li>Core should be opinionated and quirky.</li>\n\n\n\n<li>If you make WordPress, use WordPress.</li>\n\n\n\n<li>Stay close to our end-users</li>\n</ol>\n\n\n\n<figure class="wp-block-embed is-type-video is-provider-youtube wp-block-embed-youtube wp-embed-aspect-16-9 wp-has-aspect-ratio"><div class="wp-block-embed__wrapper">\n<iframe loading="lazy" class="youtube-player" width="600" height="338" src="https://www.youtube.com/embed/ELW4Jdvujbc?version=3&#038;rel=1&#038;showsearch=0&#038;showinfo=1&#038;iv_load_policy=1&#038;fs=1&#038;hl=en-US&#038;autohide=2&#038;wmode=transparent" allowfullscreen="true" style="border:0;" sandbox="allow-scripts allow-same-origin allow-popups allow-presentation allow-popups-to-escape-sandbox"></iframe>\n</div><figcaption class="wp-element-caption"><a href="https://youtu.be/ELW4Jdvujbc">Watch Matt’s project update</a> on the WordPress YouTube channel</figcaption></figure>\n\n\n\n<h2 class="wp-block-heading">Closing remarks</h2>\n\n\n\n<p>In their closing remarks, the event organizers expressed gratitude for the endorsements of the <a href="https://europe.wordcamp.org/2024/wordcamp-europe-receives-patronage-from-the-european-parliament/">European Parliament</a>, the city of Torino, and Turismo Torino, the regional tourism board. The volunteer team was celebrated for their hard work in producing the event.&nbsp;</p>\n\n\n\n<p>Closing out a robust three days of programming, the organizing team announced that <a href="https://europe.wordcamp.org/2025/">WordCamp Europe 2025</a> would be held in Basel, Switzerland, from June 5 to 7, 2025. The announcement was met with hearty applause and plans to meet in a year’s time.</p>\n\n\n\n<figure class="wp-block-image size-large"><img loading="lazy" decoding="async" width="1024" height="682" src="https://i0.wp.com/wordpress.org/news/files/2024/06/group.jpg?resize=1024%2C682&#038;ssl=1" alt="" class="wp-image-17384" srcset="https://i0.wp.com/wordpress.org/news/files/2024/06/group.jpg?resize=1024%2C682&amp;ssl=1 1024w, https://i0.wp.com/wordpress.org/news/files/2024/06/group.jpg?resize=300%2C200&amp;ssl=1 300w, https://i0.wp.com/wordpress.org/news/files/2024/06/group.jpg?resize=768%2C512&amp;ssl=1 768w, https://i0.wp.com/wordpress.org/news/files/2024/06/group.jpg?resize=1536%2C1024&amp;ssl=1 1536w, https://i0.wp.com/wordpress.org/news/files/2024/06/group.jpg?resize=2048%2C1365&amp;ssl=1 2048w" sizes="(max-width: 1000px) 100vw, 1000px" data-recalc-dims="1" /><figcaption class="wp-element-caption">Attendees gather for a photo at WCEU in Torino</figcaption></figure>\n\n\n\n<h2 class="wp-block-heading"><strong>Stay connected</strong></h2>\n\n\n\n<p><a href="https://events.wordpress.org/">WordPress events</a> enable technologists, open source enthusiasts, and community members around the globe to meet, share ideas, and collaborate to drive WordPress and the open web forward.</p>\n\n\n\n<p>Mark your calendars for <a href="https://us.wordcamp.org/2024/">WordCamp US</a> (Portland, Oregon, United States), <a href="https://wordpress.org/state-of-the-word/">State of the Word</a> (Tokyo), and next year’s <a href="https://asia.wordcamp.org/2025/">WordCamp Asia</a> in Manila!</p>\n\n\n\n<hr class="wp-block-separator has-alpha-channel-opacity" />\n\n\n\n<p>This post is a collaboration between the contributors who produce content for <a href="https://wordpress.org/news">wordpress.org/news</a> and the WordCamp Europe Communications team.</p>\n";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}}s:30:"com-wordpress:feed-additions:1";a:1:{s:7:"post-id";a:1:{i:0;a:5:{s:4:"data";s:5:"17374";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}}}}i:4;a:6:{s:4:"data";s:69:"\n		\n		\n		\n		\n		\n				\n		\n		\n		\n		\n		\n\n					\n										\n					\n		\n		\n			";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";s:5:"child";a:4:{s:0:"";a:6:{s:5:"title";a:1:{i:0;a:5:{s:4:"data";s:20:"WordPress 6.6 Beta 2";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}s:4:"link";a:1:{i:0;a:5:{s:4:"data";s:56:"https://wordpress.org/news/2024/06/wordpress-6-6-beta-2/";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}s:7:"pubDate";a:1:{i:0;a:5:{s:4:"data";s:31:"Tue, 11 Jun 2024 16:26:15 +0000";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}s:8:"category";a:5:{i:0;a:5:{s:4:"data";s:11:"Development";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}i:1;a:5:{s:4:"data";s:8:"Releases";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}i:2;a:5:{s:4:"data";s:7:"Updates";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}i:3;a:5:{s:4:"data";s:4:"beta";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}i:4;a:5:{s:4:"data";s:8:"releases";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}s:4:"guid";a:1:{i:0;a:5:{s:4:"data";s:35:"https://wordpress.org/news/?p=17355";s:7:"attribs";a:1:{s:0:"";a:1:{s:11:"isPermaLink";s:5:"false";}}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}s:11:"description";a:1:{i:0;a:5:{s:4:"data";s:342:"WordPress 6.6 Beta 2 is here! Please download and test it. This beta version of the WordPress software is under development. Please do not install, run, or test this version of WordPress on production or mission-critical websites—you risk unexpected results if you do. Instead, test Beta 2 on a local site or a testing environment [&#8230;]";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}}s:32:"http://purl.org/dc/elements/1.1/";a:1:{s:7:"creator";a:1:{i:0;a:5:{s:4:"data";s:8:"marybaum";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}}s:40:"http://purl.org/rss/1.0/modules/content/";a:1:{s:7:"encoded";a:1:{i:0;a:5:{s:4:"data";s:7673:"\n<p><br>WordPress 6.6 Beta 2 is here! Please download and test it.</p>\n\n\n\n<p id="block-79834dd4-c99a-477a-b722-091806a32976"><strong>This beta version of the WordPress software is under development. </strong>Please do not install, run, or test this version of WordPress on production or mission-critical websites—you risk unexpected results if you do.</p>\n\n\n\n<p id="block-aa4b335e-b1a2-4904-a68c-c3e73e574386">Instead, test Beta 2 on a local site or a testing environment in any of these four ways:</p>\n\n\n\n<figure class="wp-block-table"><table class="has-fixed-layout"><tbody><tr><th>Plugin</th><td>Install and activate the <a href="https://wordpress.org/plugins/wordpress-beta-tester/">WordPress Beta Tester</a> plugin on a WordPress install. (Select the “Bleeding edge” channel and “Beta/RC Only” stream).</td></tr><tr><th>Direct Download</th><td>Download the <a href="https://wordpress.org/wordpress-6.6-beta2.zip">Beta 2 version (zip)</a> and install it on a WordPress website.</td></tr><tr><th>Command Line</th><td>Use this <a href="https://make.wordpress.org/cli/">WP-CLI</a> command:<br><code>wp core update --version=6.6-beta2</code></td></tr><tr><th>WordPress Playground</th><td>Use a <a href="https://playground.wordpress.net/#{%20%22preferredVersions%22:%20{%20%22php%22:%20%228.0%22,%20%22wp%22:%20%22beta%22%20},%20%22features%22:%20{%20%22networking%22:%20true%20},%20%22steps%22:%20[%20{%20%22step%22:%20%22login%22,%20%22username%22:%20%22admin%22,%20%22password%22:%20%22password%22%20},%20{%20%22step%22:%20%22importFile%22,%20%22file%22:%20{%20%22resource%22:%20%22url%22,%20%22url%22:%20%22https://raw.githubusercontent.com/wpaccessibility/a11y-theme-unit-test/master/a11y-theme-unit-test-data.xml%22%20}%20},%20{%20%22step%22:%20%22importFile%22,%20%22file%22:%20{%20%22resource%22:%20%22url%22,%20%22url%22:%20%22https://raw.githubusercontent.com/WordPress/theme-test-data/master/themeunittestdata.wordpress.xml%22%20}%20},%20{%20%22step%22:%20%22installPlugin%22,%20%22pluginZipFile%22:%20{%20%22resource%22:%20%22wordpress.org/plugins%22,%20%22slug%22:%20%22query-monitor%22%20},%20%22options%22:%20{%20%22activate%22:%20false%20},%20%22progress%22:%20{%20%22weight%22:%202%20}%20},%20{%20%22step%22:%20%22installPlugin%22,%20%22pluginZipFile%22:%20{%20%22resource%22:%20%22wordpress.org/plugins%22,%20%22slug%22:%20%22create-block-theme%22%20},%20%22progress%22:%20{%20%22weight%22:%202%20}%20},%20{%20%22step%22:%20%22installPlugin%22,%20%22pluginZipFile%22:%20{%20%22resource%22:%20%22wordpress.org/plugins%22,%20%22slug%22:%20%22debug-bar%22%20},%20%22progress%22:%20{%20%22weight%22:%202%20}%20},%20{%20%22step%22:%20%22installPlugin%22,%20%22pluginZipFile%22:%20{%20%22resource%22:%20%22wordpress.org/plugins%22,%20%22slug%22:%20%22health-check%22%20},%20%22progress%22:%20{%20%22weight%22:%202%20}%20},%20{%20%22step%22:%20%22installPlugin%22,%20%22pluginZipFile%22:%20{%20%22resource%22:%20%22wordpress.org/plugins%22,%20%22slug%22:%20%22test-reports%22%20},%20%22progress%22:%20{%20%22weight%22:%202%20}%20},%20{%20%22step%22:%20%22installPlugin%22,%20%22pluginZipFile%22:%20{%20%22resource%22:%20%22wordpress.org/plugins%22,%20%22slug%22:%20%22user-switching%22%20},%20%22progress%22:%20{%20%22weight%22:%202%20}%20}%20]%20}">6.6 Beta 2 WordPress Playground instance</a> to test the software directly in your browser. This might be the easiest way ever—no separate sites, no setup. Just click and go!&nbsp;</td></tr></tbody></table><figcaption class="wp-element-caption">Three ways to test WordPress Beta 2.</figcaption></figure>\n\n\n\n<p id="block-7e6a92e6-dba7-4f69-9226-f4dcab4a0b91">The target release date for WordPress 6.6 is <strong>July 16, 2024</strong>. Your help testing Beta and RC versions over the next five weeks is vital to making sure the final release is everything it should be: stable, powerful, and intuitive.</p>\n\n\n\n<h2 class="wp-block-heading" id="block-aebce12b-08f8-40a7-9fe6-5a08f75d2254">If you find an issue</h2>\n\n\n\n<p id="block-b9e58289-f6cb-4bdd-85a1-eb8d9a704ae4">If you run into an issue, please share it in the&nbsp;<a href="https://wordpress.org/support/forum/alphabeta/">Alpha/Beta area</a>&nbsp;of the support forums. If you are comfortable submitting a reproducible bug report, you can do so&nbsp;<a href="https://core.trac.wordpress.org/newticket">via WordPress Trac</a>. You can also check your issue against a list of&nbsp;<a href="https://core.trac.wordpress.org/tickets/major">known bugs</a>.</p>\n\n\n\n<h2 class="wp-block-heading">The bug bounty doubles in the beta period</h2>\n\n\n\n<p>The WordPress community sponsors a&nbsp;<a href="https://make.wordpress.org/security/2024/06/04/wordpress-6-6-is-coming/">financial reward for reporting new, unreleased security vulnerabilities.</a>&nbsp;That reward doubles between Beta 1, which landed June 4, and the final Release Candidate (RC) that will happen July 9. Please follow the project’s responsible-disclosure practices detailed on this&nbsp;<a href="https://hackerone.com/wordpress">HackerOne page</a>&nbsp;and in this&nbsp;<a href="https://wordpress.org/about/security/">security white paper</a>.</p>\n\n\n\n<h2 class="wp-block-heading">The work continues</h2>\n\n\n\n<p><strong>Catch up with what&#8217;s new in 6.6:</strong> <a href="https://wordpress.org/news/2024/06/wordpress-6-6-beta-1/" data-type="post" data-id="17289">check out the Beta 1 announcement for the highlights.</a></p>\n\n\n\n<p>Beta 2 packs in more than 50 updates to the Editor since the Beta 1 release, including 40+ <a href="https://core.trac.wordpress.org/query?status=closed&amp;changetime=02%2F14%2F2024..02%2F19%2F2024&amp;milestone=6.5&amp;col=id&amp;col=milestone&amp;col=owner&amp;col=type&amp;col=priority&amp;order=id">tickets for WordPress core</a>:</p>\n\n\n\n<ul class="wp-block-list">\n<li><a href="https://github.com/WordPress/gutenberg/commits/trunk?since=2024-06-04&amp;until=2024-06-07&amp;before=c7f51bdbe10bec0c0ab7f987a3f01caaa717c1db+70" data-type="link" data-id="https://github.com/WordPress/gutenberg/commits/wp/6.5?since=2024-02-14&amp;until=2024-02-20">GitHub commits for 6.6</a> since June 4</li>\n\n\n\n<li><a href="https://core.trac.wordpress.org/query?changetime=06%2F04%2F2024..06%2F11%2F2024&amp;resolution=fixed&amp;milestone=6.6&amp;max=1000&amp;col=id&amp;col=summary&amp;col=type&amp;col=milestone&amp;col=owner&amp;col=status&amp;col=priority&amp;order=priority">Closed Trac tickets</a> since June 4</li>\n</ul>\n\n\n\n<p>The beta cycle is all about fixing the bugs you find in testing. Thanks again for this vitally important contribution to WordPress! </p>\n\n\n\n<p class="has-text-align-right is-style-default"><em>Props to <a href=\'https://profiles.wordpress.org/priethor/\' class=\'mention\'><span class=\'mentions-prefix\'>@</span>priethor</a>, <a href=\'https://profiles.wordpress.org/dansoschin/\' class=\'mention\'><span class=\'mentions-prefix\'>@</span>dansoschin</a>, <a href=\'https://profiles.wordpress.org/davidb/\' class=\'mention\'><span class=\'mentions-prefix\'>@</span>davidb</a>, <a href=\'https://profiles.wordpress.org/atachibana/\' class=\'mention\'><span class=\'mentions-prefix\'>@</span>atachibana</a>, <a href=\'https://profiles.wordpress.org/meher/\' class=\'mention\'><span class=\'mentions-prefix\'>@</span>meher</a>, <a href=\'https://profiles.wordpress.org/webcommsat/\' class=\'mention\'><span class=\'mentions-prefix\'>@</span>webcommsat</a>, and <a href=\'https://profiles.wordpress.org/juanmaguitar/\' class=\'mention\'><span class=\'mentions-prefix\'>@</span>juanmaguitar</a> for collaboration and review.</em></p>\n\n\n\n<h2 class="wp-block-heading">A Beta 2 haiku</h2>\n\n\n\n<p>Testing is vital:<br>It makes everything better.<br>Let&#8217;s find all the bugs!</p>\n";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}}s:30:"com-wordpress:feed-additions:1";a:1:{s:7:"post-id";a:1:{i:0;a:5:{s:4:"data";s:5:"17355";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}}}}i:5;a:6:{s:4:"data";s:61:"\n		\n		\n		\n		\n		\n				\n		\n		\n\n					\n										\n					\n		\n		\n\n			";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";s:5:"child";a:4:{s:0:"";a:7:{s:5:"title";a:1:{i:0;a:5:{s:4:"data";s:61:"WP Briefing: Episode 81: It’s your first WordCamp? Welcome!";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}s:4:"link";a:1:{i:0;a:5:{s:4:"data";s:78:"https://wordpress.org/news/2024/06/episode-81-its-your-first-wordcamp-welcome/";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}s:7:"pubDate";a:1:{i:0;a:5:{s:4:"data";s:31:"Mon, 10 Jun 2024 12:00:00 +0000";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}s:8:"category";a:2:{i:0;a:5:{s:4:"data";s:7:"Podcast";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}i:1;a:5:{s:4:"data";s:11:"wp-briefing";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}s:4:"guid";a:1:{i:0;a:5:{s:4:"data";s:53:"https://wordpress.org/news/?post_type=podcast&p=17352";s:7:"attribs";a:1:{s:0:"";a:1:{s:11:"isPermaLink";s:5:"false";}}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}s:11:"description";a:1:{i:0;a:5:{s:4:"data";s:373:"Get ready to dive into the vibrant world of WordCamps with this special episode of the WordPress Briefing, hosted by Josepha Haden Chomphosy! This episode is designed for first-time attendees; we’ll explore what to expect, from Contributor Day activities to mastering the art of socializing and networking. Whether you’re aiming to contribute to the WordPress [&#8230;]";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}s:9:"enclosure";a:1:{i:0;a:5:{s:4:"data";s:0:"";s:7:"attribs";a:1:{s:0:"";a:3:{s:3:"url";s:51:"https://wordpress.org/news/files/2024/06/WPB081.mp3";s:6:"length";s:1:"0";s:4:"type";s:0:"";}}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}}s:32:"http://purl.org/dc/elements/1.1/";a:1:{s:7:"creator";a:1:{i:0;a:5:{s:4:"data";s:14:"Brett McSherry";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}}s:40:"http://purl.org/rss/1.0/modules/content/";a:1:{s:7:"encoded";a:1:{i:0;a:5:{s:4:"data";s:19398:"\n<p>Get ready to dive into the vibrant world of WordCamps with this special episode of the WordPress Briefing, hosted by Josepha Haden Chomphosy! This episode is designed for first-time attendees; we’ll explore what to expect, from Contributor Day activities to mastering the art of socializing and networking. Whether you’re aiming to contribute to the WordPress community or simply looking to make new connections, this episode will help you navigate your first WordCamp with confidence and excitement. Join us for a fun and informative guide to ensure you’re prepared and energized for all the activities these dynamic events have to offer.</p>\n\n\n\n<h2 class="wp-block-heading">Credits</h2>\n\n\n\n<p>Host:&nbsp;<a href="https://profiles.wordpress.org/chanthaboune/">Josepha Haden Chomphosy</a><br>Editor:&nbsp;<a href="https://profiles.wordpress.org/dustinhartzler/">Dustin Hartzler</a><br>Logo:&nbsp;<a href="https://profiles.wordpress.org/javiarce/">Javier Arce</a><br>Production:&nbsp;<a href="https://profiles.wordpress.org/bjmcsherry/">Brett McSherry</a><br>Song: Fearless First by Kevin MacLeod</p>\n\n\n\n<h2 class="wp-block-heading">Show Notes</h2>\n\n\n\n<ul class="wp-block-list">\n<li><a href="https://asia.wordcamp.org/">WordCamp Asia</a></li>\n\n\n\n<li><a href="https://europe.wordcamp.org/">WordCamp Europe</a></li>\n\n\n\n<li><a href="https://us.wordcamp.org/">WordCamp US</a></li>\n\n\n\n<li><a href="https://events.wordpress.org/upcoming-events/filtered/type/wordcamp/">Upcoming Smaller WordCamps</a></li>\n\n\n\n<li><a href="https://learn.wordpress.org/">Learn WordPress</a><br><strong>Small List of Big Things</strong>\n<ul class="wp-block-list">\n<li><a href="https://www.surveymonkey.com/r/9T3ZFSB" target="_blank" rel="noreferrer noopener">Gender Equality in WordPress Businesses Survey</a></li>\n\n\n\n<li><a href="https://asia.wordcamp.org/2025/dates-and-venue-revealed/" target="_blank" rel="noreferrer noopener">WordCamp Asia 2025: Dates and Venue Revealed</a></li>\n\n\n\n<li><a href="https://make.wordpress.org/contribute/" target="_blank" rel="noreferrer noopener">Try the Contributor Wizard Questionnaire</a></li>\n\n\n\n<li><a href="https://make.wordpress.org/updates/2024/05/23/five-for-the-future-program-updates-may-2024/" target="_blank" rel="noreferrer noopener">Five for the Future Program Updates: May 2024</a></li>\n</ul>\n</li>\n\n\n\n<li>Have a question you’d like answered? Submit them to&nbsp;<a href="mailto:wpbriefing@WordPress.org">WPBriefing@WordPress.org</a>.</li>\n</ul>\n\n\n\n<h2 class="wp-block-heading">Transcript</h2>\n\n\n\n<span id="more-17352"></span>\n\n\n\n<p>[00:00:00] <strong>Josepha:</strong> Hello, everyone, and welcome to the WordPress Briefing, the podcast where you can catch quick explanations of the ideas behind the WordPress open source project, some insight into the community that supports it, and get a small list of big things coming up in the next two weeks. I&#8217;m your host, Josepha Haden Chomphosy. Here we go.</p>\n\n\n\n<p>[00:00:28] (Intro Music) </p>\n\n\n\n<p>[00:00:40] <strong>Josepha:</strong> A pivotal moment in my WordPress journey was when someone invited me to a WordCamp. I was sort of aware of WordPress, but certainly not aware of the community or the ways of open source. And when I look back, there were a few things I wish I had known going in. I am, of course, an unapologetic extrovert and therefore unstoppable at events, but if you are headed to your first WordCamp and are feeling a little nervous or confused, then pop in some earbuds because the next 10 minutes are for you.</p>\n\n\n\n<p>[00:01:11] <strong>Josepha:</strong> We&#8217;re going to first take a look at some basic tactical things about WordCamps, and then I&#8217;m going to tell you a few, like, human things about being a human going to events. If you&#8217;re a dog going to these events, I think that your prep is different, but also that is not my area of expertise. So the first thing, some tactical stuff about going to WordCamps. All of this happens before you even get in the front door. And so this is stuff that you can do in the comfort of your own home, on your own time, using your own computer. If you&#8217;ve got questions, you&#8217;ve got a search engine nearby to take some quick searches. Make sure you know what you&#8217;re talking about.</p>\n\n\n\n<p>But first things first, the shape of a WordCamp. All WordCamps have at least one day of talks, one social event, and sponsors to connect to. Some also have extra events that you need to sign up for, like Contributor Days, workshops, things like that. But we&#8217;ll start with the main event, right? We&#8217;re going to start with the day of talks and things.</p>\n\n\n\n<p>[00:02:09] <strong>Josepha:</strong> So when we&#8217;re looking at the main event of a WordCamp, what you should do is you should head to the WordCamp&#8217;s website and check out the schedule. I suggest that you plan for two, maybe three things that you might want to learn and look around at the schedule to see if there are any presenters or presentations that look like they fit those things that you think you might want to learn. Because if it&#8217;s not working for you, if it&#8217;s not teaching you something, then you don&#8217;t necessarily need to be in that one. Even if you&#8217;re not sure about a session a talk that you&#8217;re planning to go to, I recommend that you stop by, and then if you find out that it&#8217;s not for you, you can leave again.  That&#8217;s fine. But I do encourage you to go to at least one thing that feels a little bit outside of your comfort zone. Even if you feel lost right now. It at least gives you an idea of what to search for once you do get to that point. I would never have known the things to search for early on in my learning of WordPress without going to at least one or two sessions that were just way over my head. </p>\n\n\n\n<p>[00:03:14] <strong>Josepha:</strong> Second thing is don&#8217;t forget to check when lunch is available. And if you have dietary restrictions, let them know ahead of time. I realize this sounds silly, and I don&#8217;t know about you, but I can&#8217;t focus when I&#8217;m hungry. But also, it&#8217;s really a great, low-stakes networking time, and I think one of the overlooked networking times as well. I mean, everyone&#8217;s gotta eat, right? And it&#8217;s easier to strike up a conversation over a meal than just out of thin air or, you know, in the middle of a presentation when you&#8217;re supposed to be listening to a talk. So yeah, check out when lunch is happening! And yeah, make a friend or two, sit down at a table, and ask somebody what they&#8217;re doing with WordPress and how long they&#8217;ve been doing it.</p>\n\n\n\n<p>And the third thing that I would recommend that you do when you&#8217;re looking at kind of the main event for a WordCamp is to schedule in time to wander around and meet the event sponsors. They are all experts in some WordPress problem or other, so probably they have a solution to a problem that you have got. But they&#8217;re also how we keep our prices super low, so even if you have no problems or you think you have no problems. Still, check them out. They&#8217;re also staffed with wonderful people that are building really cool stuff with WordPress and so you might just get some inspiration out there. </p>\n\n\n\n<p>[00:04:28] <strong>Josepha:</strong> Now for the side events.</p>\n\n\n\n<p>So the side events, we&#8217;re going to kind of start close to the main event and work our way out. So you&#8217;ve got generally three types of side events if you don&#8217;t count the networking things, which, in this case, I&#8217;m not. But just know that almost every WordCamp has some networking event, either an after-party or, like, a happy hour, a social that happens before the event.</p>\n\n\n\n<p>You&#8217;ll get emails about those if you have signed up for updates on the website. Also, you can look on the website directly. Just check out the schedule. Always go to those. The networking is the best at a WordCamp. But the side events—we&#8217;re talking about specific types. Like I said, we&#8217;re going to start close and work our way out.</p>\n\n\n\n<p>[00:05:11] <strong>Josepha:</strong> So, workshops. These are just what they sound like. They&#8217;re classroom-style opportunities to practice the things you&#8217;ve learned at meetup events or on learn.WordPress.org, depending on how you found your way to this WordCamp. They mostly happen during the WordCamp itself. in a separate track, and there are like stacks of workshops in that track in that series of sessions. But a lot of them do require preregistration simply so that the trainer has an idea of how many people to expect. Again, if you get in the workshop and it&#8217;s way over your head, you feel like you absolutely cannot get it done, you&#8217;re always welcome to leave and check out some other area. But, in general, the workshops that we have WordCamps are pretty solid.</p>\n\n\n\n<p>So a little bit further removed from that are our Youth and Teen Days. So this is more of an event series that is specifically designed for teens or kids who are trying to learn more about WordPress and other related business and entrepreneurial topics. It&#8217;s kind of a catch all but also has a lot of WordPress content in it. They have age limits, of course, and require separate registration for safety and planning purposes both. And those, in general, are either half-day during the WordCamp itself or a full-day during that WordCamp. </p>\n\n\n\n<p>[00:06:32] <strong>Josepha:</strong> Which brings us then to the big one, the major side event. This is a full-day side event called Contributor Day. If your WordCamp has a Contributor Day, it will happen either the day before or the day after the WordCamp itself. It is an entire day where attendees come together to learn how to contribute to the future of the WordPress open source project. Now, if you are listening to this as part of, like, you&#8217;re getting ready to go to a WordCamp, and you don&#8217;t know what I meant by open source or open source project or WordPress open source project, that&#8217;s fine.</p>\n\n\n\n<p>[00:07:08] <strong>Josepha:</strong> You&#8217;re going to learn all about it at the Contributor Day if you go, but the TLDR is that this software that you are about to choose to build your website on is built by thousands of people across the planet who are looking for the best solutions to problems that they have in their businesses that probably you will encounter or have encountered before. There&#8217;s no new problems under the sun, and open source methodologies kind of use the collective wisdom of everybody who has ever worked with a WordPress project or site and ran into a problem that they had to solve on their own, like this open source project, this community of people just make sure that that wisdom is collected and standardized and made available for all of eternity.</p>\n\n\n\n<p>That&#8217;s all you need to know. Low key. I&#8217;ve made Contributor Days sound so calming. However, that is a whole day thing. It happens before or after the WordCamp. It has separate registration so that organizers of your WordCamp can plan for how many folks need to be there to teach new and returning contributors, what to do. If I&#8217;m going to be honest, if you&#8217;re going to get overwhelmed at any WordPress event, it&#8217;s going to be one of these, but they are well worth the effort.</p>\n\n\n\n<p>[00:08:30] <strong>Josepha:</strong> Even if you just make a single contribution and never return, which I hope is not the case for you. I hope you do return. Even if you make a single contribution and never return, there&#8217;s something really grounding about seeing how much expertise and time, and care goes into this software that is, against all odds, completely free. So that&#8217;s all the tactical stuff, or a lot of it anyway.</p>\n\n\n\n<p>It at least gives you a sense for what you&#8217;re getting yourself into for your first-ever wonderful WordPress weekend. But I promised you some human stuff too. So here is my considerably shorter list of stuff to bring as a human being going to a WordCamp. There&#8217;s an optional one. I&#8217;ll start you off with an optional one. Come with an idea of what you think you want to learn. You don&#8217;t have to come with that if you don&#8217;t want to. Some of us don&#8217;t know what we don&#8217;t know yet, and that&#8217;s fine too. But if you have a sense for what you think you need to learn, you&#8217;ll have an easier time figuring out how to spend your time while you&#8217;re here.</p>\n\n\n\n<p>[00:09:30] <strong>Josepha:</strong> So, the non-optional things. Bring some way to exchange information. It can be QR codes, business cards, or pen and paper. It doesn&#8217;t really matter as long as it&#8217;s something that works for you to be sharing information with people that you meet. Because you never know when you&#8217;re going to meet your business soulmate, but the odds that you&#8217;re going to do it at a WordCamp are pretty dang high.</p>\n\n\n\n<p>The second thing to bring is bring what you need to be comfortable. Bring your water bottle, a change of shoes if you need it, spare battery for your phone, your glasses. This day is going to be long enough without worrying about small inconveniences. So bring what you need to make yourself comfortable. </p>\n\n\n\n<p>[00:10:09] <strong>Josepha:</strong> And finally bring your bravery. You will not know by looking at someone whether they&#8217;ve been doing WordPress stuff for two years or two weeks. But you can know that at some point, they were in the first two days of trying to figure this all out. One of the most endearing things about this community is the zeal they bring to solving a problem. So if you get lost or stuck, just ask the person next to you. We all remember what it was like to know nothing, and we are rooting for you to succeed. And that&#8217;s it. That&#8217;s your whole list. That&#8217;s everything you need to know to be the most prepared first-time attendee to a WordCamp ever. If that all sounded more overwhelming than just showing up, don&#8217;t worry.</p>\n\n\n\n<p>You can also just show up. That&#8217;s what I did. And even though I knew next to nothing, those WordCampers made me feel welcome and included and kept me coming back to learn more.</p>\n\n\n\n<p>[00:11:04] <strong>Josepha:</strong> Ah, WordCamps. Gosh, I love those things. So glad that we&#8217;re all getting back together for them.&nbsp;</p>\n\n\n\n<p>[00:11:10] (Music interlude) </p>\n\n\n\n<p>[00:11:18] <strong>Josepha:</strong> That brings us now, my friends, to our small list of big things. If you&#8217;re a first-time WordPresser, if you&#8217;ve never been to a WordCamp, and you don&#8217;t know what any of these things are, don&#8217;t worry; you can still go take a look at them, or you can wait until later when you&#8217;re less overwhelmed.</p>\n\n\n\n<p>Either way, but this is our small list of big things for middle of the year 2024. First thing on my list, the gender equality in WordPress businesses survey is still open. It aims to gain critical insight into the gender composition of leadership teams, the experiences of women and gender-diverse leaders and employees, and also take a look at the challenges and barriers to their career success. I care deeply about making sure that we have a way for folks who are traditionally and historically underrepresented in technology have a way to get into our space. Obviously, women and nonbinary folks are an area that I feel particularly called to help build those on-ramps for, but I have a great concern for that across the entire ecosystem and any intersection that we run into as we get more and more users into our space. </p>\n\n\n\n<p>[00:12:30] <strong>Josepha:</strong> If you are a woman, if you work with women, if you work in WordPress, if you work in a WordPress business, go take that survey, and let&#8217;s see what we find out about what it&#8217;s like to work in this space, as somebody that we normally don&#8217;t see. </p>\n\n\n\n<p>The second thing on our list is that WordCamp Asia 2025 dates and venue have been revealed. So WordCamp Asia 2023 and 2024 were both major successes, and we are excited to share that the dates and venue for next year will be February 20th, 21st, 22nd in 2025 in Manila, and you&#8217;ll be able to go over to that website, take a look at it, we&#8217;ll have a link in the show notes as always and maybe start planning your your next big Asian adventure.</p>\n\n\n\n<p>[00:13:13] <strong>Josepha:</strong> The third thing on my list is this new contributor wizard questionnaire. So, there are more than 20 teams to contribute to in the WordPress project. They all show up at those Contributor Days that I talked about. But there are more than 20 of them. They work on different parts of the WordPress project every day. And our passionate community offers contribution opportunities for everyone. I know, we know, that finding the right team is the key to a meaningful contributor experience. So, our interactive questionnaire is here to help you determine where to start. It is sometimes difficult to know whether you can contribute to a software if you are a designer, if you are a writer, if you are in marketing.</p>\n\n\n\n<p>And it turns out that you can contribute to WordPress with a bunch of skills that you otherwise would not have realized. So, we&#8217;ll have a link to the questionnaire in the show notes again. Also, it&#8217;s probably going to pop up on WordCamp sites, Contributor Day sites, anything that helps you all understand where you might find a little bit of success as a contributor is a good place for it to be. Take the questionnaire, see where you land, the WordPress sorting hat. </p>\n\n\n\n<p>[00:14:18] <strong>Josepha:</strong> And item number four. So we&#8217;ve made some updates, not we&#8217;ve made some updates, we have some updates from the Five for the Future program. So the Five for the Future program has a long history in the WordPress project. There are a couple of different episodes in this podcast where you can learn more about it.</p>\n\n\n\n<p>But, to bolster transparency and openness, we have an update on the current state of WordPress contributions as of the end of May 2024. In the past few months, we&#8217;ve made a lot of efforts to improve the program and contributor experience in WordPress. We&#8217;ve also done a little bit of work to kind of clean up the pledges that are in there for, people or companies or teams that have found that they couldn&#8217;t continue their contributions over time. That is fine too. But we&#8217;ll have a link to that update in the show notes as well.</p>\n\n\n\n<p>[00:15:09] <strong>Josepha:</strong> And that, my friends, is your small list of big things. Don&#8217;t forget to follow us on your favorite podcast app or subscribe directly on WordPress.org/news. You&#8217;ll get a friendly reminder whenever there&#8217;s a new episode. If you liked what you heard today, share it with a fellow WordPresser. Or, if you had questions about what you heard, you can share those with me at WPBriefing@WordPress.org. I am your host, Josepha Haden Chomposy. Thanks for tuning in today for the WordPress Briefing, and I&#8217;ll see you again in a couple of weeks. </p>\n\n\n\n<p>[00:15:36] (Music outro) </p>\n";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}}s:30:"com-wordpress:feed-additions:1";a:1:{s:7:"post-id";a:1:{i:0;a:5:{s:4:"data";s:5:"17352";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}}}}i:6;a:6:{s:4:"data";s:57:"\n		\n		\n		\n		\n		\n				\n		\n\n					\n										\n					\n		\n		\n			";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";s:5:"child";a:4:{s:0:"";a:6:{s:5:"title";a:1:{i:0;a:5:{s:4:"data";s:35:"WordPress 6.5.4 Maintenance Release";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}s:4:"link";a:1:{i:0;a:5:{s:4:"data";s:71:"https://wordpress.org/news/2024/06/wordpress-6-5-4-maintenance-release/";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}s:7:"pubDate";a:1:{i:0;a:5:{s:4:"data";s:31:"Wed, 05 Jun 2024 15:57:15 +0000";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}s:8:"category";a:1:{i:0;a:5:{s:4:"data";s:8:"Releases";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}s:4:"guid";a:1:{i:0;a:5:{s:4:"data";s:35:"https://wordpress.org/news/?p=17340";s:7:"attribs";a:1:{s:0:"";a:1:{s:11:"isPermaLink";s:5:"false";}}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}s:11:"description";a:1:{i:0;a:5:{s:4:"data";s:345:"WordPress 6.5.4 is now available!This minor release features 5 bug fixes in Core. You can review a summary of the maintenance updates in this release by reading the Release Candidate announcement. WordPress 6.5.4 is a short-cycle release. The next major release will be version 6.6 planned for July 2024. If you have sites that support [&#8230;]";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}}s:32:"http://purl.org/dc/elements/1.1/";a:1:{s:7:"creator";a:1:{i:0;a:5:{s:4:"data";s:12:"Aaron Jorbin";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}}s:40:"http://purl.org/rss/1.0/modules/content/";a:1:{s:7:"encoded";a:1:{i:0;a:5:{s:4:"data";s:4663:"\n<p><strong>WordPress 6.5.4 is now available!</strong><br>This minor release features <a href="https://core.trac.wordpress.org/query?status=closed&amp;milestone=6.5.4&amp;group=status&amp;col=id&amp;col=summary&amp;col=owner&amp;col=type&amp;col=priority&amp;col=component&amp;col=version&amp;col=keywords&amp;order=priority">5 bug fixes in Core</a>. You can review a summary of the maintenance updates in this release by reading the <a href="https://make.wordpress.org/core/2024/05/30/wordpress-6-5-4-rc1-is-now-available/">Release Candidate announcement</a>.</p>\n\n\n\n<p>WordPress 6.5.4 is a short-cycle release. The next major release will be <a href="https://make.wordpress.org/core/6-6/">version 6.6</a> planned for July 2024.</p>\n\n\n\n<p>If you have sites that support automatic background updates, the update process will begin automatically.</p>\n\n\n\n<p>You can <a href="https://wordpress.org/wordpress-6.5.4.zip">download WordPress 6.5.4 from WordPress.org</a>, or visit your WordPress Dashboard, click “Updates”, and then click “Update Now”.</p>\n\n\n\n<p>For more information on this release, please <a href="https://wordpress.org/support/wordpress-version/version-6-5-4">visit the HelpHub site</a>.</p>\n\n\n\n<h2 class="wp-block-heading">Thank you to these WordPress contributors</h2>\n\n\n\n<p>This release was led by <a href="https://profiles.wordpress.org/hellofromTonya">Tonya Mork</a>, <a href="https://profiles.wordpress.org/costdev">Colin Stewart</a>, and <a href="https://profiles.wordpress.org/jorbin">Aaron Jorbin</a>.</p>\n\n\n\n<p>WordPress 6.5.4 would not have been possible without the contributions of the following people. Their asynchronous coordination to deliver maintenance fixes into a stable release is a testament to the power and capability of the WordPress community.</p>\n\n\n\n<p class="is-style-wporg-props-medium"><a href="//profiles.wordpress.org/jorbin&quot;">Aaron Jorbin</a>, <a href="https://profiles.wordpress.org/adrianduffell">adrianduffell</a>, <a href="https://profiles.wordpress.org/azaozz">Andrew Ozz</a>, <a href="https://profiles.wordpress.org/afragen">Andy Fragen</a>, <a href="https://profiles.wordpress.org/beaulebens">Beau Lebens</a>, <a href="https://profiles.wordpress.org/bernhard-reiter/">Bernhard Reiter</a>, <a href="https://profiles.wordpress.org/ironprogrammer">Brian Alexander</a>, <a href="https://profiles.wordpress.org/costdev">Colin Stewart</a>, <a href="https://profiles.wordpress.org/nerrad">Darren Ethier (nerrad)</a>, <a href="https://profiles.wordpress.org/davidbaumwald/">David Baumwald</a>, <a href="https://profiles.wordpress.org/lopo">Enrico Battocchi</a>, <a href="https://profiles.wordpress.org/estelaris/">Estela Rueda</a>, <a href="https://profiles.wordpress.org/johnjamesjacoby">John James Jacoby</a>, <a href="https://profiles.wordpress.org/johnbillion">John Blackbourn</a>, <a href="https://profiles.wordpress.org/desrosj">Jonathan Desrosiers</a>, <a href="https://profiles.wordpress.org/kevinwhoffman">Kevin Hoffman</a>, <a href="https://profiles.wordpress.org/louiswol94">Louis Wolmarans</a>, <a href="https://profiles.wordpress.org/hmbashar">Md Abul Bashar</a>, <a href="https://profiles.wordpress.org/illuminea">Miriam Schwab</a>, <a href="https://profiles.wordpress.org/mukesh27">Mukesh Panchal</a>, <a href="https://profiles.wordpress.org/narenin">Narendra Sishodiya</a>, <a href="https://profiles.wordpress.org/swissspidy">Pascal Birchler</a>, <a href="https://profiles.wordpress.org/peterwilsoncc">Peter Wilson</a>, <a href="https://profiles.wordpress.org/pooja1210">Pooja N Muchandikar</a>, <a href="https://profiles.wordpress.org/mikachan">Sarah Norris</a>, <a href="https://profiles.wordpress.org/coffee2code/">Scott Reilly</a>, <a href="https://profiles.wordpress.org/smub">Syed Balkhi</a>, <a href="https://profiles.wordpress.org/hellofromTonya">Tonya Mork</a></p>\n\n\n\n<h2 class="wp-block-heading">How to contribute</h2>\n\n\n\n<p>To get involved in WordPress core development, head over to Trac, <a href="https://core.trac.wordpress.org/report/6">pick a ticket</a>, and join the conversation in the <a href="https://wordpress.slack.com/archives/C02RQBWTW">#core</a> and <a href="https://wordpress.slack.com/archives/C06U06K50Q5">#6-6-release-leads</a> channels. Need help? Check out the <a href="https://make.wordpress.org/core/handbook/">Core Contributor Handbook</a>.</p>\n\n\n\n<p class="has-text-align-right"><em>Props to @<a href="https://profiles.wordpress.org/afragen/">afragen</a>, @<a href="https://profiles.wordpress.org/hellofromtonya/">hellofromtonya</a> , and </em><a href="https://profiles.wordpress.org/angelasjin/">@<em>angelasjin</em></a><em> for proofreading.</em></p>\n";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}}s:30:"com-wordpress:feed-additions:1";a:1:{s:7:"post-id";a:1:{i:0;a:5:{s:4:"data";s:5:"17340";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}}}}i:7;a:6:{s:4:"data";s:66:"\n		\n		\n		\n		\n		\n				\n		\n		\n		\n		\n\n					\n										\n					\n		\n		\n			";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";s:5:"child";a:4:{s:0:"";a:6:{s:5:"title";a:1:{i:0;a:5:{s:4:"data";s:20:"WordPress 6.6 Beta 1";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}s:4:"link";a:1:{i:0;a:5:{s:4:"data";s:56:"https://wordpress.org/news/2024/06/wordpress-6-6-beta-1/";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}s:7:"pubDate";a:1:{i:0;a:5:{s:4:"data";s:31:"Tue, 04 Jun 2024 17:44:29 +0000";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}s:8:"category";a:4:{i:0;a:5:{s:4:"data";s:11:"Development";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}i:1;a:5:{s:4:"data";s:8:"Releases";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}i:2;a:5:{s:4:"data";s:4:"beta";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}i:3;a:5:{s:4:"data";s:8:"releases";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}s:4:"guid";a:1:{i:0;a:5:{s:4:"data";s:35:"https://wordpress.org/news/?p=17289";s:7:"attribs";a:1:{s:0:"";a:1:{s:11:"isPermaLink";s:5:"false";}}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}s:11:"description";a:1:{i:0;a:5:{s:4:"data";s:351:"WordPress 6.6 Beta 1 is here! Please download and test it. This beta version of the WordPress software is under development. Please do not install, run, or test this version of WordPress on production or mission-critical websites—you risk unexpected results if you do. Instead, install Beta 1 on local sites and testing environments in any [&#8230;]";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}}s:32:"http://purl.org/dc/elements/1.1/";a:1:{s:7:"creator";a:1:{i:0;a:5:{s:4:"data";s:8:"marybaum";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}}s:40:"http://purl.org/rss/1.0/modules/content/";a:1:{s:7:"encoded";a:1:{i:0;a:5:{s:4:"data";s:16244:"\n<p>WordPress 6.6 Beta 1 is here! Please download and test it.</p>\n\n\n\n<p><strong>This beta version of the WordPress software is under development. </strong>Please do not install, run, or test this version of WordPress on production or mission-critical websites—you risk unexpected results if you do.</p>\n\n\n\n<p>Instead, install Beta 1 on local sites and testing environments in any of these four ways:</p>\n\n\n\n<figure class="wp-block-table"><table><tbody><tr><th>Plugin</th><td>Install and activate the <a href="https://wordpress.org/plugins/wordpress-beta-tester/">WordPress Beta Tester</a> plugin on a WordPress install. (Select the “Bleeding edge” channel and “Beta/RC Only” stream).</td></tr><tr><th>Direct Download</th><td>Download the <a href="https://wordpress.org/wordpress-6.6-beta1.zip">Beta 1 version (zip)</a> and install it on a WordPress website.</td></tr><tr><th>Command Line</th><td>Use this <a href="https://make.wordpress.org/cli/">WP-CLI</a> command:<br><code>wp core update --version=6.6-beta1</code></td></tr><tr><th>WordPress Playground</th><td>Use a <a href="https://playground.wordpress.net/#{%20%22preferredVersions%22:%20{%20%22php%22:%20%228.0%22,%20%22wp%22:%20%22beta%22%20},%20%22features%22:%20{%20%22networking%22:%20true%20},%20%22steps%22:%20[%20{%20%22step%22:%20%22login%22,%20%22username%22:%20%22admin%22,%20%22password%22:%20%22password%22%20},%20{%20%22step%22:%20%22importFile%22,%20%22file%22:%20{%20%22resource%22:%20%22url%22,%20%22url%22:%20%22https://raw.githubusercontent.com/wpaccessibility/a11y-theme-unit-test/master/a11y-theme-unit-test-data.xml%22%20}%20},%20{%20%22step%22:%20%22importFile%22,%20%22file%22:%20{%20%22resource%22:%20%22url%22,%20%22url%22:%20%22https://raw.githubusercontent.com/WordPress/theme-test-data/master/themeunittestdata.wordpress.xml%22%20}%20},%20{%20%22step%22:%20%22installPlugin%22,%20%22pluginZipFile%22:%20{%20%22resource%22:%20%22wordpress.org/plugins%22,%20%22slug%22:%20%22query-monitor%22%20},%20%22options%22:%20{%20%22activate%22:%20false%20},%20%22progress%22:%20{%20%22weight%22:%202%20}%20},%20{%20%22step%22:%20%22installPlugin%22,%20%22pluginZipFile%22:%20{%20%22resource%22:%20%22wordpress.org/plugins%22,%20%22slug%22:%20%22create-block-theme%22%20},%20%22progress%22:%20{%20%22weight%22:%202%20}%20},%20{%20%22step%22:%20%22installPlugin%22,%20%22pluginZipFile%22:%20{%20%22resource%22:%20%22wordpress.org/plugins%22,%20%22slug%22:%20%22debug-bar%22%20},%20%22progress%22:%20{%20%22weight%22:%202%20}%20},%20{%20%22step%22:%20%22installPlugin%22,%20%22pluginZipFile%22:%20{%20%22resource%22:%20%22wordpress.org/plugins%22,%20%22slug%22:%20%22health-check%22%20},%20%22progress%22:%20{%20%22weight%22:%202%20}%20},%20{%20%22step%22:%20%22installPlugin%22,%20%22pluginZipFile%22:%20{%20%22resource%22:%20%22wordpress.org/plugins%22,%20%22slug%22:%20%22test-reports%22%20},%20%22progress%22:%20{%20%22weight%22:%202%20}%20},%20{%20%22step%22:%20%22installPlugin%22,%20%22pluginZipFile%22:%20{%20%22resource%22:%20%22wordpress.org/plugins%22,%20%22slug%22:%20%22user-switching%22%20},%20%22progress%22:%20{%20%22weight%22:%202%20}%20}%20]%20}" data-type="link" data-id="https://playground.wordpress.net/#{%20%22preferredVersions%22:%20{%20%22php%22:%20%228.0%22,%20%22wp%22:%20%22beta%22%20},%20%22features%22:%20{%20%22networking%22:%20true%20},%20%22steps%22:%20[%20{%20%22step%22:%20%22login%22,%20%22username%22:%20%22admin%22,%20%22password%22:%20%22password%22%20},%20{%20%22step%22:%20%22importFile%22,%20%22file%22:%20{%20%22resource%22:%20%22url%22,%20%22url%22:%20%22https://raw.githubusercontent.com/wpaccessibility/a11y-theme-unit-test/master/a11y-theme-unit-test-data.xml%22%20}%20},%20{%20%22step%22:%20%22importFile%22,%20%22file%22:%20{%20%22resource%22:%20%22url%22,%20%22url%22:%20%22https://raw.githubusercontent.com/WordPress/theme-test-data/master/themeunittestdata.wordpress.xml%22%20}%20},%20{%20%22step%22:%20%22installPlugin%22,%20%22pluginZipFile%22:%20{%20%22resource%22:%20%22wordpress.org/plugins%22,%20%22slug%22:%20%22query-monitor%22%20},%20%22options%22:%20{%20%22activate%22:%20false%20},%20%22progress%22:%20{%20%22weight%22:%202%20}%20},%20{%20%22step%22:%20%22installPlugin%22,%20%22pluginZipFile%22:%20{%20%22resource%22:%20%22wordpress.org/plugins%22,%20%22slug%22:%20%22create-block-theme%22%20},%20%22progress%22:%20{%20%22weight%22:%202%20}%20},%20{%20%22step%22:%20%22installPlugin%22,%20%22pluginZipFile%22:%20{%20%22resource%22:%20%22wordpress.org/plugins%22,%20%22slug%22:%20%22debug-bar%22%20},%20%22progress%22:%20{%20%22weight%22:%202%20}%20},%20{%20%22step%22:%20%22installPlugin%22,%20%22pluginZipFile%22:%20{%20%22resource%22:%20%22wordpress.org/plugins%22,%20%22slug%22:%20%22health-check%22%20},%20%22progress%22:%20{%20%22weight%22:%202%20}%20},%20{%20%22step%22:%20%22installPlugin%22,%20%22pluginZipFile%22:%20{%20%22resource%22:%20%22wordpress.org/plugins%22,%20%22slug%22:%20%22test-reports%22%20},%20%22progress%22:%20{%20%22weight%22:%202%20}%20},%20{%20%22step%22:%20%22installPlugin%22,%20%22pluginZipFile%22:%20{%20%22resource%22:%20%22wordpress.org/plugins%22,%20%22slug%22:%20%22user-switching%22%20},%20%22progress%22:%20{%20%22weight%22:%202%20}%20}%20]%20}">6.6 Beta 1 WordPress Playground instance</a> to test the software directly in your browser. This might be the easiest way ever—no separate sites, no setup. Just click and go!&nbsp;</td></tr></tbody></table></figure>\n\n\n\n<p>The scheduled final release date for WordPress 6.6 is <strong>July 16, 2024</strong>. Your help testing Beta and RC versions over the next six weeks is vital to making sure the final release is everything it should be: stable, powerful, and intuitive.</p>\n\n\n\n<h2 class="wp-block-heading">How important is your testing? </h2>\n\n\n\n<p><strong>Features in this Beta release may be changed or removed between now and the final release.</strong> Early attention from testers like you is critical to finding and reporting potential bugs, usability issues, or compatibility problems to make sure developers can address them before the final release. You don&#8217;t need any contribution experience, and this is a fantastic way to begin your WordPress contributor story!</p>\n\n\n\n<h2 class="wp-block-heading">If you find an issue</h2>\n\n\n\n<p>If you run into an issue, please share it in the <a href="https://wordpress.org/support/forum/alphabeta/">Alpha/Beta area</a> of the support forums. If you are comfortable submitting a reproducible bug report, you can do so <a href="https://core.trac.wordpress.org/newticket">via WordPress Trac</a>. You can also check your issue against a list of <a href="https://core.trac.wordpress.org/tickets/major">known bugs</a>.</p>\n\n\n\n<p>Want to know more about testing in general, and how to get started? Follow the <a href="https://make.wordpress.org/test/">testing initiatives in Make Core</a> and join the <a href="https://wordpress.slack.com/messages/core-test/">#core-test channel</a> on <a href="https://wordpress.slack.com/">Making WordPress Slack</a>.</p>\n\n\n\n<p>Like every version since 5.0 in 2018, WordPress 6.6 will integrate a host of new features from the last several releases of the Gutenberg plugin. Learn more about Gutenberg updates since WordPress 6.5 in the <a href="https://make.wordpress.org/core/tag/gutenberg-new/">What’s New in Gutenberg</a> posts for versions <a href="https://make.wordpress.org/core/2024/02/28/whats-new-in-gutenberg-17-8-28-february/">17.8</a>, <a href="https://make.wordpress.org/core/2024/03/13/whats-new-in-gutenberg-17-9-13-march/">17.9</a>, <a href="https://make.wordpress.org/core/2024/03/27/whats-new-in-gutenberg-18-0-27-march/">18.0</a>, <a href="https://make.wordpress.org/core/2024/04/10/whats-new-in-gutenberg-18-1-10-april/">18.1</a>, <a href="https://make.wordpress.org/core/2024/04/24/whats-new-in-gutenberg-18-2-24-april/">18.2</a>, <a href="https://make.wordpress.org/core/2024/05/08/whats-new-in-gutenberg-18-3-8-may/">18.3</a>, and <a href="https://make.wordpress.org/core/2024/05/23/whats-new-in-gutenberg-18-4-22-may/">18.4</a>. The final version will also include Gutenberg 18.5; the Beta 2 post will link to that.</p>\n\n\n\n<p class="is-style-default">WordPress 6.6 Beta 1 contains 97 enhancements and 101 fixes for the editor, in a total of about 206 <a href="https://core.trac.wordpress.org/query?status=closed&amp;milestone=6.6&amp;group=component&amp;max=500&amp;col=id&amp;col=summary&amp;col=owner&amp;col=type&amp;col=priority&amp;col=component&amp;col=version&amp;order=priority">tickets for WordPress 6.6 Core</a>.</p>\n\n\n\n<h2 class="wp-block-heading">The vulnerability bounty doubles in the beta period</h2>\n\n\n\n<p>The WordPress community sponsors a <a href="https://make.wordpress.org/security/2024/06/04/wordpress-6-6-is-coming/">monetary reward for reporting new, unreleased security vulnerabilities.</a> That reward doubles during the period between Beta 1 on June 4 and the final Release Candidate (RC) that will happen June 25. Please follow the project&#8217;s responsible-disclosure practices detailed on this <a href="https://hackerone.com/wordpress">HackerOne page</a> and in this <a href="https://wordpress.org/about/security/">security white paper</a>.</p>\n\n\n\n<h2 class="wp-block-heading">What’s coming to WordPress 6.6?</h2>\n\n\n\n<p>This year’s second major release is about polish and finesse. Features that landed in the last few releases have new flexibility and smoother flows—and a few new tricks. And of course there are a few brand-new features.</p>\n\n\n\n<h3 class="wp-block-heading">Data Views updates</h3>\n\n\n\n<p>Part of the groundwork for phase 3, Data Views get new and improved experience of working with information in the Site Editor. A new layout consolidates patterns and template parts, gets you to general management views in fewer clicks, and packs in a wide range of refinements.</p>\n\n\n\n<h3 class="wp-block-heading">Overrides in synced patterns</h3>\n\n\n\n<p>What if you could keep a synced pattern‘s <em>look and feel</em> everywhere it appears—keeping it on brand—but have different <em>content</em> everywhere it appears?</p>\n\n\n\n<p>For instance, maybe you‘re building a pattern for recipes. Ideally, you want to keep the overall design of the recipe card consistent on every post that will have a recipe. But the recipe itself—the ingredients, the steps, special notes on technique—will be different every time.</p>\n\n\n\n<p>And perhaps, in the future, other people might need to change the design of the recipe pattern. It would be nice to know they can do that, and that the content in existing recipes will stay right where it is.</p>\n\n\n\n<p>In version 6.6, you can make all that happen, and overrides in synced patterns are the way you do it.</p>\n\n\n\n<h3 class="wp-block-heading">See all the blocks</h3>\n\n\n\n<p>Up to now, when you had a block selected and then opened the block Inserter, you only saw the blocks you were allowed to add to your selected block. Where were all the others?</p>\n\n\n\n<p>In 6.6, when you have a block selected, you get two lists. First, there&#8217;s the list of blocks you can insert at your selected block. Then you get a list with all the other blocks. So you can get an idea of what you can use in your selected block, and what other blocks you could use in another area. In fact, if you select a block from that second list, WordPress 6.6 will add it below your block, to use in whatever you build next.</p>\n\n\n\n<h3 class="wp-block-heading">A new publish flow</h3>\n\n\n\n<p>Version 6.6 brings the post and site editors closer together than ever. So whether you’re writing for a post in the post editor or a page in the Site Editor, your experience will be about the same.</p>\n\n\n\n<h3 class="wp-block-heading">Style variations</h3>\n\n\n\n<p>If a block theme comes with style variations, 6.6 vastly expands your design options right out of the box, without installing or configuring a single thing. Because in 6.6, your theme  pulls the color palettes and typography style sets out of its installed variations to let you mix and match for a whole world of expanded creative expression.</p>\n\n\n\n<h3 class="wp-block-heading">Section styles </h3>\n\n\n\n<p>Do you build themes? Now you can define style options for separate sections of multiple blocks, including inner blocks.</p>\n\n\n\n<p>Then your users can apply those block style variations to entire groups of blocks, effectively creating branded sections they can curate across a site.</p>\n\n\n\n<h4 class="wp-block-heading">A note about CSS specificity</h4>\n\n\n\n<p>To make it easier for your variations to override the global styles CSS, those styles now come wrapped in `:root`. That limits their specificity. <a href="https://github.com/WordPress/gutenberg/discussions/61810">For details, read the full discussion on GitHub.</a></p>\n\n\n\n<h3 class="wp-block-heading">A native Grid layout</h3>\n\n\n\n<p>Grid is a new variation for the Group block that lets you arrange the blocks inside it as a grid. If you&#8217;ve been using a plugin for this, now you can make your grids natively.</p>\n\n\n\n<h3 class="wp-block-heading">Better pattern management in Classic themes</h3>\n\n\n\n<p>You heard right: You can do everything with patterns in Classic themes that you can in a block theme. You can see all the patterns available to you in a single view and insert a pattern on the fly. </p>\n\n\n\n<h3 class="wp-block-heading">Negative. Margins.</h3>\n\n\n\n<p>They&#8217;re here: negative margin values, so you can make objects overlap in your design. As a guardrail, you can only set a negative margin by typing an actual negative number, not by using the slider. That’s to keep people from adding negative values they didn&#8217;t intend.</p>\n\n\n\n<h3 class="wp-block-heading">Rollback auto-updates</h3>\n\n\n\n<p>Now you can have the convenience of setting all your plugins to auto-update and the inner peace you get from knowing that if anything goes wrong, 6.6 will do a rollback. Automatically.</p>\n\n\n\n<p><strong><em>This post <strong><em>reflects the latest changes</em></strong> as of June 4, 2024.</em></strong> </p>\n\n\n\n<p><strong>Again, the features in this first beta may change, based on what testers like you find.</strong></p>\n\n\n\n<p>Get an overview of the <a href="https://make.wordpress.org/core/6-6/">6.6 release cycle</a>, and check the <a href="https://make.wordpress.org/core/">Make WordPress Core blog</a> for <a href="https://make.wordpress.org/core/tag/6-6/">6.6-related posts</a> in the next few weeks for further details.</p>\n\n\n\n<h3 class="wp-block-heading">Just for you: a Beta 1 haiku</h3>\n\n\n\n<p>Negative margins<br>Embellish all the new ways<br>To design and build  </p>\n\n\n\n<p class="has-text-align-left is-style-default"><em>Thanks very much to <a href=\'https://profiles.wordpress.org/meher/\' class=\'mention\'><span class=\'mentions-prefix\'>@</span>meher</a>, <a href=\'https://profiles.wordpress.org/audrasjb/\' class=\'mention\'><span class=\'mentions-prefix\'>@</span>audrasjb</a>, <a href=\'https://profiles.wordpress.org/fabiankaegy/\' class=\'mention\'><span class=\'mentions-prefix\'>@</span>fabiankaegy</a>, <a href=\'https://profiles.wordpress.org/colorful-tones/\' class=\'mention\'><span class=\'mentions-prefix\'>@</span>colorful-tones</a>, </em><a href=\'https://profiles.wordpress.org/davidbaumwald/\' class=\'mention\'><span class=\'mentions-prefix\'>@</span>davidbaumwald</a>,<em> <a href=\'https://profiles.wordpress.org/dansoschin/\' class=\'mention\'><span class=\'mentions-prefix\'>@</span>dansoschin</a>, <a href=\'https://profiles.wordpress.org/desrosj/\' class=\'mention\'><span class=\'mentions-prefix\'>@</span>desrosj</a>, <a href=\'https://profiles.wordpress.org/atachibana/\' class=\'mention\'><span class=\'mentions-prefix\'>@</span>atachibana</a>, <a href=\'https://profiles.wordpress.org/ehtis/\' class=\'mention\'><span class=\'mentions-prefix\'>@</span>ehtis</a>, <a href=\'https://profiles.wordpress.org/adamsilverstein/\' class=\'mention\'><span class=\'mentions-prefix\'>@</span>adamsilverstein</a>, <a href=\'https://profiles.wordpress.org/joedolson/\' class=\'mention\'><span class=\'mentions-prefix\'>@</span>joedolson</a>, and <a href=\'https://profiles.wordpress.org/webcommsat/\' class=\'mention\'><span class=\'mentions-prefix\'>@</span>webcommsat</a> for reviewing and collaborating on this post!</em></p>\n";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}}s:30:"com-wordpress:feed-additions:1";a:1:{s:7:"post-id";a:1:{i:0;a:5:{s:4:"data";s:5:"17289";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}}}}i:8;a:6:{s:4:"data";s:63:"\n		\n		\n		\n		\n		\n				\n		\n		\n		\n\n					\n										\n					\n		\n		\n			";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";s:5:"child";a:4:{s:0:"";a:6:{s:5:"title";a:1:{i:0;a:5:{s:4:"data";s:69:"WordCamp Europe 2024: Mid-Year Update and Q&amp;A with Matt Mullenweg";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}s:4:"link";a:1:{i:0;a:5:{s:4:"data";s:99:"https://wordpress.org/news/2024/05/wordcamp-europe-2024-mid-year-update-and-qa-with-matt-mullenweg/";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}s:7:"pubDate";a:1:{i:0;a:5:{s:4:"data";s:31:"Fri, 31 May 2024 16:45:04 +0000";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}s:8:"category";a:3:{i:0;a:5:{s:4:"data";s:6:"Events";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}i:1;a:5:{s:4:"data";s:8:"WordCamp";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}i:2;a:5:{s:4:"data";s:4:"WCEU";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}s:4:"guid";a:1:{i:0;a:5:{s:4:"data";s:35:"https://wordpress.org/news/?p=17286";s:7:"attribs";a:1:{s:0:"";a:1:{s:11:"isPermaLink";s:5:"false";}}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}s:11:"description";a:1:{i:0;a:5:{s:4:"data";s:217:"WordCamp Europe 2024 kicks off on June 13, gathering WordPressers from across the globe to Torino, Italy. Find out more about the conference and how to live stream project Cofounder Matt Mullenweg\'s mid-year update. ";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}}s:32:"http://purl.org/dc/elements/1.1/";a:1:{s:7:"creator";a:1:{i:0;a:5:{s:4:"data";s:12:"Lauren Stein";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}}s:40:"http://purl.org/rss/1.0/modules/content/";a:1:{s:7:"encoded";a:1:{i:0;a:5:{s:4:"data";s:2144:"\n<p>WordCamp Europe 2024 kicks off on June 13, gathering WordPressers from across the globe to Torino, Italy. </p>\n\n\n\n<p>The highly anticipated conference has a packed schedule starting with <a href="https://europe.wordcamp.org/2024/contributor-day/">Contributor Day</a> and will feature a notable roster of speakers. Other highlights will include <a href="https://europe.wordcamp.org/2024/workshops/">engaging workshops</a> covering a variety of disciplines (including one for youth and teens) and <a href="https://europe.wordcamp.org/2024/wordcamp-connect/">WordCamp Connect</a>, a dedicated space for attendees to meet and network with additional community-led sessions.</p>\n\n\n\n<p>The conference will conclude with an exciting mid-year project update from WordPress Cofounder Matt Mullenweg, including a live Q&amp;A session. You can watch Matt’s presentation on June 15, 2024, streaming live on the <a href="https://youtube.com/wordpress">WordPress YouTube channel</a> starting at 4:30 p.m. Central European Summer Time (2:30 p.m. UTC).</p>\n\n\n\n<p><strong>What:</strong> <a href="https://europe.wordcamp.org/2024/session/wordpress-project-summer-update/" data-type="link" data-id="https://europe.wordcamp.org/2024/session/wordpress-project-summer-update/">WordPress Project Summer Update</a> + Q&amp;A Session with Matt Mullenweg<br><strong>When: </strong>June 15, 2024 at 2:30 p.m. UTC (Start of live stream)<br><strong>Where: </strong><a href="https://europe.wordcamp.org/2024/venue/">Lingotto Conference and Exhibition Centre<strong><br></strong></a><strong>Streaming: </strong><a href="https://youtube.com/wordpress">Watch the live stream</a> on the WordPress YouTube channel.</p>\n\n\n\n<h2 class="wp-block-heading">Have a question for Matt?</h2>\n\n\n\n<p>If you’re unable to attend WordCamp Europe 2024 in person, you’re welcome to <a href="mailto:ask-matt@wordcamp.org">email your questions</a> instead. Given the number of questions expected both in-person and online, only some of the submitted questions may be answered live. </p>\n\n\n\n<p>Whether you’re touching down in Torino or streaming from elsewhere, see you very soon!</p>\n";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}}s:30:"com-wordpress:feed-additions:1";a:1:{s:7:"post-id";a:1:{i:0;a:5:{s:4:"data";s:5:"17286";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}}}}i:9;a:6:{s:4:"data";s:61:"\n		\n		\n		\n		\n		\n				\n		\n		\n\n					\n										\n					\n		\n		\n\n			";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";s:5:"child";a:4:{s:0:"";a:7:{s:5:"title";a:1:{i:0;a:5:{s:4:"data";s:86:"WP Briefing: Episode 80: Unlocking Your WordPress Potential with Learn WordPress Tools";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}s:4:"link";a:1:{i:0;a:5:{s:4:"data";s:108:"https://wordpress.org/news/2024/05/episode-80-unlocking-your-wordpress-potential-with-learn-wordpress-tools/";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}s:7:"pubDate";a:1:{i:0;a:5:{s:4:"data";s:31:"Mon, 27 May 2024 12:00:00 +0000";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}s:8:"category";a:2:{i:0;a:5:{s:4:"data";s:7:"Podcast";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}i:1;a:5:{s:4:"data";s:11:"wp-briefing";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}s:4:"guid";a:1:{i:0;a:5:{s:4:"data";s:53:"https://wordpress.org/news/?post_type=podcast&p=17278";s:7:"attribs";a:1:{s:0:"";a:1:{s:11:"isPermaLink";s:5:"false";}}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}s:11:"description";a:1:{i:0;a:5:{s:4:"data";s:493:"Welcome to another episode of the WordPress Briefing! In this episode, your host, Josepha Haden Chomphosy, delves into the incredible resources available to help you broaden your WordPress expertise. Whether you\'re just starting out or looking to deepen your skillset, these tools and tutorials offer something for everyone. Join us as we explore how Learn WordPress can be your guide on the journey to mastering WordPress, providing invaluable support and community connections along the way.";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}s:9:"enclosure";a:1:{i:0;a:5:{s:4:"data";s:0:"";s:7:"attribs";a:1:{s:0:"";a:3:{s:3:"url";s:60:"https://wordpress.org/news/files/2024/05/WPB80-2Enhanced.mp3";s:6:"length";s:1:"0";s:4:"type";s:0:"";}}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}}s:32:"http://purl.org/dc/elements/1.1/";a:1:{s:7:"creator";a:1:{i:0;a:5:{s:4:"data";s:14:"Brett McSherry";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}}s:40:"http://purl.org/rss/1.0/modules/content/";a:1:{s:7:"encoded";a:1:{i:0;a:5:{s:4:"data";s:14785:"\n<p>Welcome to another episode of the WordPress Briefing! In this episode, your host, Josepha Haden Chomphosy, delves into the incredible resources available to help you broaden your WordPress expertise. Whether you&#8217;re just starting out or looking to deepen your skillset, these tools and tutorials offer something for everyone. Join us as we explore how Learn WordPress can be your guide on the journey to mastering WordPress, providing invaluable support and community connections along the way.</p>\n\n\n\n<h2 class="wp-block-heading">Credits</h2>\n\n\n\n<p>Host:&nbsp;<a href="https://profiles.wordpress.org/chanthaboune/">Josepha Haden Chomphosy</a><br>Editor:&nbsp;<a href="https://profiles.wordpress.org/dustinhartzler/">Dustin Hartzler</a><br>Logo:&nbsp;<a href="https://profiles.wordpress.org/javiarce/">Javier Arce</a><br>Production:&nbsp;<a href="https://profiles.wordpress.org/bjmcsherry/">Brett McSherry</a><br>Song: Fearless First by Kevin MacLeod</p>\n\n\n\n<h2 class="wp-block-heading">Show Notes</h2>\n\n\n\n<ul class="wp-block-list">\n<li><a href="https://events.wordpress.org/">WordPress Events </a></li>\n\n\n\n<li><a href="https://learn.wordpress.org/">Learn WordPress</a>\n<ul class="wp-block-list">\n<li><a href="https://learn.wordpress.org/online-workshops/">Online Workshops</a></li>\n\n\n\n<li><a href="https://learn.wordpress.org/tutorials/">Tutorials</a></li>\n\n\n\n<li><a href="https://learn.wordpress.org/lesson-plans/">Lesson Plans</a></li>\n</ul>\n</li>\n\n\n\n<li><strong>Small List of Big Things</strong>\n<ul class="wp-block-list">\n<li><a href="https://europe.wordcamp.org/2024/youth-teens-workshop-at-wordcamp-europe-2024/" target="_blank" rel="noreferrer noopener">WordCamp Europe Youth &amp; Teen Workshop Registration is Open</a></li>\n\n\n\n<li><a href="https://make.wordpress.org/core/2024/05/03/roadmap-to-6-6/" target="_blank" rel="noreferrer noopener">Roadmap to WordPress 6.6</a></li>\n\n\n\n<li><a href="https://us.wordcamp.org/2024/introducing-showcase-day/" target="_blank" rel="noreferrer noopener">WordCamp US 2024 Showcase Day</a></li>\n\n\n\n<li><a href="https://make.wordpress.org/community/2024/04/08/share-your-feedback-with-meetup-com/">Share Feedback with&nbsp;Meetup.com</a></li>\n</ul>\n</li>\n\n\n\n<li>Have a question you&#8217;d like answered? Submit them to&nbsp;<a href="mailto:wpbriefing@WordPress.org">WPBriefing@WordPress.org</a>.</li>\n</ul>\n\n\n\n<h2 class="wp-block-heading">Transcript</h2>\n\n\n\n<span id="more-17278"></span>\n\n\n\n<p>[00:00:10] <strong>Josepha:</strong> Hello, everyone, and welcome to the WordPress Briefing, the podcast where you can catch quick explanations of the ideas behind the WordPress open source project, some insight into the community that supports it, and get a small list of big things coming up in the next two weeks. I&#8217;m your host, Josepha Haden Chomphosy.</p>\n\n\n\n<p>Here we go!</p>\n\n\n\n<p>[00:00:28] (Intro Music)&nbsp;</p>\n\n\n\n<p>[00:00:40] <strong>Josepha:</strong> My friends, I don&#8217;t know about where you live, but where I live, it&#8217;s graduation season. Students all across the region are either gearing down for a little bit of a brain break or gearing up for the next big adventure in their lives. And as I watch these students discover the next phases in their lives, whether it looks good or bad, whether it feels fearful or faithful, I can&#8217;t help but think back to my last big change.</p>\n\n\n\n<p>[00:01:07] <strong>Josepha:</strong> The one that brought me here to WordPress. I was working in insurance at the time and investing in a side hustle. And as is often the case with side hustles, discovered that knowing something about marketing myself was going to be key. Now, this next bit, I know that a lot of you will understand immediately. After that realization, I entered a period in my life where I was learning how to invest in my hoped-for side hustle so that I could realize my hoped-for dreams while also having to succeed at the job that I was using to pay my bills.</p>\n\n\n\n<p>By some singular coincidence, I wound up being introduced to the WordPress project, where I found not only the tools it turned out I needed but also people who were willing to help me learn them. For me, during that time, the cost to get access to both the tool and that support was basically zero. Like the whole cost to me was get those WordPress people together in a room to talk about WordPress for an hour.</p>\n\n\n\n<p>[00:02:04] <strong>Josepha:</strong> And that&#8217;s something that I always want to do anyway. I always want to get people together. And if what we&#8217;re talking about is WordPress, and that is what I need to learn about, then so be it. I realize that there is a little bit of privilege in that story and a whole lot of persistence. It&#8217;s not like I discovered it, and overnight, everything worked out well, and perfectly, and correctly.</p>\n\n\n\n<p>However, all of the struggles to get what I got accomplished done aside. One of the things that I love the most about how the WordPress project has evolved over time is that we took that already low-cost, low-barrier concept and did everything in our power to take that low-cost, low-barrier and make it available to as many people as possible in as many points in their journey as possible.</p>\n\n\n\n<p>So, if you&#8217;re at the start of your career or thinking about a bit of a career change, I have some resources for you. Like, stick around. But before we get to the resources, I want to make sure that you hear this. Learning WordPress things, whether that&#8217;s the software itself, or how to run a business supported by WordPress, or how to support other businesses by building them WordPress stuff, learning these skills now is an investment in who you want to be.</p>\n\n\n\n<p>[00:03:20] <strong>Josepha:</strong> It&#8217;s placing a bet that&#8217;s grounded in what you think you can bring to the world before anyone else might have figured out it&#8217;s what they need in their lives. And when you do that, in WordPress, you&#8217;re accessing and hopefully one day contributing to an equitable framework that doesn&#8217;t require you to understand it in order for you to benefit from it.</p>\n\n\n\n<p>You can do hard things, and hopefully, these resources make those hard things a little easier. I&#8217;m going to take us through a whirlwind wayfinding list. I&#8217;ll generally be focused on time required and then kind of like necessary actions or context that would be useful for you to know. But remember that your mileage may vary.</p>\n\n\n\n<p>[00:04:01] <strong>Josepha:</strong> If something sounds close but not perfect, I encourage you to give it a try anyway. The worst that happens is you try something different next time. Or, in the best-case scenario, you create something that other folks also have been missing. There was something that was close for them but not perfect either, and maybe you found the thing that&#8217;s perfect for them.</p>\n\n\n\n<p>So, here is my whirlwind wayfinding list. Let&#8217;s go. Only have one hour a week and prefer a little company in your learning? Check out a meetup event near you. You can find those listed in your dashboard or on events.WordPress.org, but frequently, they happen during the week, after work hours, sometimes they happen on the weekend, they happen like in libraries or coffee shops.</p>\n\n\n\n<p>So, there are a lot of different ways that these events come together, and surely, there will be something that is the sort of low-key event that you want. But if not, you can always reach out to your local chapter and see how you can get involved with that, how you can help them create a new meetup event.</p>\n\n\n\n<p>[00:05:02] <strong>Josepha:</strong> The next option, if you only have an hour a week, but you actually don&#8217;t want company but still use some external support, I would check out one of our online workshops. There are cohorts for each workshop, and they&#8217;re run by facilitators so that you can learn and socialize from the comfort and safety of your own space, or if you really are super strapped for time, that can help with like not having to commute anywhere. Next up on our list, feel like you could average an hour a week, but honestly, would prefer it to be in one big chunk? Check out a WordCamp near you.</p>\n\n\n\n<p>Those are a little bit like the meetups but quite a bit bigger and a lot more content, a lot more learning available, and gets you into a different kind of group of people in your local area. Those happen about once a year per city or region, but if there&#8217;s not one within a comfortable traveling distance for you, it might be a good chance for you to do a mini business trip, or if you&#8217;re doing it as current career development, see if your boss, or your boss self, if you are your own boss, has a continuing education budget available for you.</p>\n\n\n\n<p>[00:06:08] <strong>Josepha:</strong> Have 30 minutes or so a week and don&#8217;t need any external motivation? On the one hand, I am a little jealous. I sometimes need my own external motivation. But, if that&#8217;s not you, if you can just self-drive forever, then courses over on learn.WordPress.org are just about your speed. We even have a series of learning pathways in development that curate all the courses you need to achieve particular milestones.</p>\n\n\n\n<p>You can also help to create those. If you have been all the way through your learning journey and you&#8217;re, like, the most WordPressy WordPresser we&#8217;ve ever seen, and you just want to make sure that other people have the same opportunities you&#8217;ve had, that&#8217;s an excellent opportunity to show up and make sure that the knowledge is still available, still free, still can be accessed.</p>\n\n\n\n<p>And finally, if you have unpredictable time and also still comfortable being completely self-driven, We have in the WordPress ecosystem countless videos, blogs, tutorials, and a ton of content creators that are behind them that specialize in teaching WordPress basics but also leveling up existing knowledge. And if your type of existing knowledge is in the, like, gathering the network to succeed, sort of area. We even have podcasts and blogs that are dedicated to the more businessy side of WordPress, how to make this function in the WordPress ecosystem.</p>\n\n\n\n<p>[00:07:32] <strong>Josepha:</strong> As always, I&#8217;ll have links for everything in the show notes—just myriad links because this isn&#8217;t even all that we need to share with you today. And I&#8217;m going to say this last thing one more time because I really, really mean it like a whole, whole lot. I know it&#8217;s hard, bordering on impossible sometimes, to carve out time to learn new things. But when you&#8217;re ready to invest in yourself, I&#8217;m pretty sure that these resources will be here to support your hoped-for dreams.</p>\n\n\n\n<p>[00:07:58] (Music interlude)&nbsp;</p>\n\n\n\n<p>[00:08:05] <strong>Josepha:</strong> And that brings us now to our small list of big things. First up is speaking of learning, speaking of investing in your future. WordCamp Europe has a youth and teen workshop going on. The registration for that is still open. It is open for students aged 10 to 16. It&#8217;s gonna be a hands-on workshop. They&#8217;ll get to build their own website with WordPress and then explore some cutting-edge technology from VR to AI and learn essential internet safety skills. We&#8217;re going to be running that on June 13th. It will be in both English and Italian. I will leave a link to the registration in the show notes.</p>\n\n\n\n<p>And the next thing on our list is pretty much related. It&#8217;s kind of related. At WordCamp US this year, we have a Showcase Day. Now, this is new to WordCamp US, and it&#8217;s all about pushing the boundaries of what WordPress can do. It will feature presentations, demos, and technical workshops for all kinds of projects, from high-profile, large-scale builds with innovative integrations to more niche creative implementations that still have a big impact. Submissions are now open for it. If you are working on something that is really cool and uses WordPress and want to show it off to the WordPress community, wander over there, submit your project; let&#8217;s take a look at it and see if we can get it into that showcase lineup, but if you are looking for inspiration about what WordPress can do, if you&#8217;re still figuring out how this can work the best for you, that&#8217;s going to be a great opportunity to look at some unusual implementations so that you can get an idea for how big this thing can get.</p>\n\n\n\n<p>[00:09:43] <strong>Josepha:</strong> And just some tactical things. The next two things on my small of big things are two tactical items. One is that WordPress 6.6 is on the move; as always, we have Beta 1 scheduled pretty soon here. So, dig into our priority features. I will leave a link to the roadmap for WordPress 6.6. We&#8217;re targeting, if I recall correctly, middle of July for that release. And so it&#8217;s coming up faster than you think. And we would absolutely love for you to come in, test the Beta, tell us what&#8217;s broken so that we can fix it before it gets out. We can&#8217;t fix the things if you don&#8217;t tell us they&#8217;re broken. </p>\n\n\n\n<p>[00:10:17] <strong>Josepha:</strong> And then the final thing on our small list of big things is that speaking of not being able to fix things that we don&#8217;t know are broken. So, we use meetup.com to manage all of our meetup series. Well, most of our meetup series anyway, but they are planning to invest in some product improvements, and they have asked for feedback from the WordPress community. Historically, we are one of the largest, most active communities on their platform. And so, if you could fill out the feedback form, if you&#8217;ve been to a meetup, or if you tried to find a meetup using meetup.com and did not succeed, that&#8217;s probably also relevant information. I&#8217;ll have a link to that here as well. It will go directly to their product team. And hopefully we&#8217;ll see some product improvements for the WordPress community in the future.</p>\n\n\n\n<p>[00:11:01] <strong>Josepha:</strong> And that, my friends, is your small list of big things. Don&#8217;t forget to follow us, follow me on your favorite podcast app, or subscribe directly on WordPress.org/news. You&#8217;ll get a friendly reminder whenever there&#8217;s a new episode, and if you liked what you heard today, share it with a fellow WordPresser. Or, if you had questions about what you heard, you can share those with me at WPBriefing@WordPress.org. I&#8217;m your host, Josepha Haden Chomphosy. Thanks again, and I&#8217;ll see you in a couple of weeks.&nbsp;</p>\n\n\n\n<p>[00:11:29] (Music outro)&nbsp;</p>\n";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}}s:30:"com-wordpress:feed-additions:1";a:1:{s:7:"post-id";a:1:{i:0;a:5:{s:4:"data";s:5:"17278";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}}}}}}s:27:"http://www.w3.org/2005/Atom";a:1:{s:4:"link";a:1:{i:0;a:5:{s:4:"data";s:0:"";s:7:"attribs";a:1:{s:0:"";a:3:{s:4:"href";s:32:"https://wordpress.org/news/feed/";s:3:"rel";s:4:"self";s:4:"type";s:19:"application/rss+xml";}}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}}s:44:"http://purl.org/rss/1.0/modules/syndication/";a:2:{s:12:"updatePeriod";a:1:{i:0;a:5:{s:4:"data";s:9:"\n	hourly	";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}s:15:"updateFrequency";a:1:{i:0;a:5:{s:4:"data";s:4:"\n	1	";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}}s:30:"com-wordpress:feed-additions:1";a:1:{s:4:"site";a:1:{i:0;a:5:{s:4:"data";s:8:"14607090";s:7:"attribs";a:0:{}s:8:"xml_base";s:0:"";s:17:"xml_base_explicit";b:0;s:8:"xml_lang";s:0:"";}}}}}}}}}}}}s:4:"type";i:128;s:7:"headers";O:48:"WpOrg\\Requests\\Utility\\CaseInsensitiveDictionary":1:{s:7:"\0*\0data";a:12:{s:6:"server";s:5:"nginx";s:4:"date";s:29:"Tue, 25 Jun 2024 05:26:55 GMT";s:12:"content-type";s:34:"application/rss+xml; charset=UTF-8";s:4:"vary";s:37:"Accept-Encoding, accept, content-type";s:25:"strict-transport-security";s:12:"max-age=3600";s:6:"x-olaf";s:3:"⛄";s:13:"last-modified";s:29:"Mon, 24 Jun 2024 19:10:30 GMT";s:4:"link";s:63:"<https://wordpress.org/news/wp-json/>; rel="https://api.w.org/"";s:15:"x-frame-options";s:10:"SAMEORIGIN";s:16:"content-encoding";s:4:"gzip";s:7:"alt-svc";s:19:"h3=":443"; ma=86400";s:4:"x-nc";s:9:"HIT ord 2";}}s:5:"build";s:14:"20211220193300";}', 'no'),
