	(150, 1, '2024-05-27 14:27:06', '2024-05-27 06:27:06', '<!-- wp:heading {"level":3} -->\n<h3 class="wp-block-heading"><strong>Executive Team</strong></h3>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li><strong>CEO</strong>: Lorem Ipsum</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>CFO</strong>: Dolor Sit</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>COO</strong>: Amet Consectetur</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>CTO</strong>: Adipiscing Elit</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {"level":3} -->\n<h3 class="wp-block-heading"><strong>Administration</strong></h3>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li><strong>Executive Assistant</strong>: Nulla Porttitor</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Office Manager</strong>: Ligula Eget</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {"level":3} -->\n<h3 class="wp-block-heading"><strong>Marketing Department</strong></h3>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li><strong>VP of Marketing</strong>: Ultricies Nisi</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Marketing Manager</strong>: Morbi Hendrerit</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Content Strategist</strong>: Sit Amet</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Social Media Manager</strong>: Consectetur Adipiscing</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Graphic Designer</strong>: Elit Mauris</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {"level":3} -->\n<h3 class="wp-block-heading"><strong>Sales Department</strong></h3>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li><strong>VP of Sales</strong>: Vehicula Magna</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Sales Manager</strong>: Curabitur Tempus</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Account Executive</strong>: Aenean Vulputate</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Sales Representative</strong>: Nunc Vehicula</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {"level":3} -->\n<h3 class="wp-block-heading"><strong>Human Resources</strong></h3>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li><strong>HR Director</strong>: Egestas Pharetra</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>HR Manager</strong>: Nam Efficitur</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Recruiter</strong>: Dui Vel</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {"level":3} -->\n<h3 class="wp-block-heading"><strong>IT Department</strong></h3>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li><strong>IT Director</strong>: Augue Laoreet</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Network Administrator</strong>: Sed Vulputate</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>System Analyst</strong>: Nulla Facilisi</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Help Desk Support</strong>: Pellentesque Habitant</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {"level":3} -->\n<h3 class="wp-block-heading"><strong>Product Development</strong></h3>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li><strong>VP of Product Development</strong>: Morbi Ultricies</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Product Manager</strong>: Etiam Ligula</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Lead Developer</strong>: Fusce Dolor</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Software Engineer</strong>: Duis Sagittis</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Quality Assurance</strong>: Ipsum Primis</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {"level":3} -->\n<h3 class="wp-block-heading"><strong>Finance Department</strong></h3>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li><strong>Controller</strong>: Orci Varius</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Accountant</strong>: Penatibus Magnis</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Financial Analyst</strong>: Parturient Montes</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Payroll Specialist</strong>: Nascetur Ridiculus</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {"level":3} -->\n<h3 class="wp-block-heading"><strong>Customer Support</strong></h3>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li><strong>Customer Support Manager</strong>: Mus Nascetur</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Support Specialist</strong>: Ridiculus Pellentesque</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Customer Service Representative</strong>: Parturient Dolor</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>This structure can be adapted or expanded based on the specific needs of your project. It serves as a template for organizing roles within a hypothetical company using "lorem ipsum" text to fill in names and positions.</p>\n<!-- /wp:paragraph -->', 'Organization Structure', '', 'inherit', 'closed', 'closed', '', '149-revision-v1', '', '', '2024-05-27 14:27:06', '2024-05-27 06:27:06', '', 149, 'http://localhost/?p=150', 0, 'revision', '', 0),
	(152, 1, '2024-05-27 14:41:48', '2024-05-27 06:41:48', '<!-- wp:media-text {"mediaId":11,"mediaType":"image"} -->\n<div class="wp-block-media-text is-stacked-on-mobile"><figure class="wp-block-media-text__media"><img src="http://localhost/wp-content/uploads/2024/05/EDITED-IMG_0198-edited-scaled.jpg" alt="DA-CBC Front Image of the building" class="wp-image-11 size-full"/></figure><div class="wp-block-media-text__content"><!-- wp:html -->\n<p class="sm:block hidden">The <strong>Crop Biotechnology Center (CBC) </strong>is one of three biotechnology centers under the <a href="https://www.da.gov.ph/" target="_blank" rel="noreferrer noopener nofollow"><strong>Department of Agriculture </strong>(DA)</a>. It serves as a catalyst in the development of and utilization of modern biotechnologies for agriculture. It rationalizes and implements the research, development, and extension agenda of the DA-Biotech Program. </p>\n<!-- /wp:html --></div></div>\n<!-- /wp:media-text -->\n\n<!-- wp:block {"ref":192} /-->\n\n<!-- wp:html -->\n<p class="sm:hidden block">The <strong>Crop Biotechnology Center (CBC) </strong>is one of three biotechnology centers under the <strong>Department of Agriculture </strong>(DA). It serves as a catalyst in the development of and utilization of modern biotechnologies for agriculture. It rationalizes and implements the research, development, and extension agenda of the DA-Biotech Program. </p>\n<!-- /wp:html -->\n\n<!-- wp:block {"ref":192} /-->\n\n<!-- wp:paragraph -->\n<p>It also provides biotechnology capacity-building services to a network of R4D institution in the use of modern crop biotechnologies. <strong>DA-CBC</strong> focuses on applying advanced technologies that contribute to the improvement in performance, yield, and quality of important commodities, such as rice, corn, coconut, and high value crops, such as mango, garlic, onion, eggplant, tomato, cotton, rubber, cassava, sweet potato, yam, cacao, papaya, banana, and abaca.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:block {"ref":192} /-->\n\n<!-- wp:paragraph -->\n<p>Currently, the <strong>DA-CBC</strong> is located within the <a href="https://www.philrice.gov.ph/" data-type="link" data-id="https://www.philrice.gov.ph/" target="_blank" rel="noreferrer noopener nofollow"><strong>Philippine Rice Research Institute</strong> (<strong>PhilRice</strong>)</a> compound. This strategic placement within PhilRice facilitates synergies with ongoing research efforts, ensuring seamless collaboration and exchange of expertise. It also provides a conducive environment for interdisciplinary interactions, fostering innovation and accelerating the development and adoption of biotechnological advancements in agriculture.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:block {"ref":192} /-->\n\n<!-- wp:image {"id":336,"sizeSlug":"full","linkDestination":"none"} -->\n<figure class="wp-block-image size-full"><img src="http://localhost/wp-content/uploads/2024/05/CBC-Photo-by-JCBerto-10-edited-scaled.jpg" alt="Philippine Rice Research Institute Compound Aerial Shot " class="wp-image-336"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:block {"ref":192} /-->\n\n<!-- wp:block {"ref":192} /-->\n\n<!-- wp:html -->\n<button class="accordion active">Vision</button>\n<div class="panel" style="max-height: 100vh;">\n<!-- /wp:html -->\n\n<!-- wp:pullquote {"style":{"typography":{"fontSize":"16px"}}} -->\n<figure class="wp-block-pullquote" style="font-size:16px"><blockquote><p>A prosperous, secure, and sustainable food future - one crop at a time.</p><cite>DA-CBC Vision</cite></blockquote></figure>\n<!-- /wp:pullquote -->\n\n<!-- wp:html -->\n</div>\n<!-- /wp:html -->\n\n<!-- wp:html -->\n<button class="accordion active">Mission</button>\n<div class="panel" style="max-height: 100vh;">\n<!-- /wp:html -->\n\n<!-- wp:pullquote {"style":{"border":{"radius":"0px","width":"0px","style":"none"},"typography":{"fontSize":"16px"}}} -->\n<figure class="wp-block-pullquote" style="border-style:none;border-width:0px;border-radius:0px;font-size:16px"><blockquote><p>To improve the productivity and competitiveness of priority commodities through providing biotechnology capacity building services, fostering collaboration within the agricultural research community, and driving the development and utilization of modern and inclusive biotechnologies for crop improvement, contributing to a resilient and prosperous agricultural landscape.</p><cite>DA-CBC Mission</cite></blockquote></figure>\n<!-- /wp:pullquote -->\n\n<!-- wp:html -->\n</div>\n<!-- /wp:html -->\n\n<!-- wp:html -->\n<button class="accordion">AO No. 26 of 2021</button>\n<div class="panel">\n  <p>Reorientation and Strengthening of the Department of Agriculture Biotechnology Centers for the Advancement of Biotechnology Research for Development and Innovation, Amending DA Administrative Order No. 06 series of 2015</p>\n<iframe src="https://www.da.gov.ph/wp-content/uploads/2021/09/ao26_s2021.pdf#view=FitH" class="w-full h-[50vh]"></iframe>\n</div>\n<!-- /wp:html -->\n\n<!-- wp:html -->\n<button class="accordion">R4D Areas</button>\n<div class="panel">\n  <ul class="show-bullet">\n<li>Genetics</li>\n<li>Genetic Engineering and Gene Editing</li>\n<li>Tissue Culture</li>\n<li>Microbial Biotechnology</li>\n<li>Diagnostics</li>\n<li>Bioinformatics and Computational Biology</li>\n<li>Natural Products, Natural Ingredients, and Value-Adding</li>\n</ul>\n</div>\n<!-- /wp:html -->\n\n<!-- wp:block {"ref":192} /-->\n\n<!-- wp:block {"ref":192} /-->', 'What is DA-CBC?', '', 'publish', 'closed', 'closed', '', 'what-is-da-cbc', '', '', '2024-06-18 20:05:27', '2024-06-18 12:05:27', '', 119, 'http://localhost/?page_id=152', 1, 'page', '', 0),
	(153, 1, '2024-05-27 14:41:48', '2024-05-27 06:41:48', '<!-- wp:paragraph -->\n<p>The <strong>Crop Biotechnology Center (CBC) </strong>is one of three biotechnology centers under the <strong>Department of Agriculture </strong>(DA). It serves as a catalyst in the development of and utilization of modern biotechnologies for agriculture. It rationalizes and implements the research, development, and extension agenda of the DA-Biotech Program. It also provides biotechnology capacity-building services to a network of R4D institution in the use of modern crop biotechnologies.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>DA-CBC</strong> focuses on applying advanced technologies that contribute to the improvement in performance, yield, and quality of important commodities, such as rice, corn, coconut, and high value crops, such as mango, garlic, onion, eggplant, tomato, cotton, rubber, cassava, sweet potato, yam, cacao, papaya, banana, and abaca.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {"textAlign":"center"} -->\n<h2 class="wp-block-heading has-text-align-center">R4D AREAS</h2>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Genetics</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Genetic Engineering and Gene Editing</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Tissue Culture</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Microbial Biotechnology</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Diagnostics</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Bioinformatics and Computational Biology</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Natural Products, Natural Ingredients, and Value-Adding</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {"textAlign":"center"} -->\n<h2 class="wp-block-heading has-text-align-center">Laboratories</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p><strong>Molecular Genetics</strong><ul><li>Functional genomic approaches to accelerate crop breeding and production</li></ul></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->', 'What is DA-CBC?', '', 'inherit', 'closed', 'closed', '', '152-revision-v1', '', '', '2024-05-27 14:41:48', '2024-05-27 06:41:48', '', 152, 'http://localhost/?p=153', 0, 'revision', '', 0),
	(154, 1, '2024-05-27 14:42:12', '2024-05-27 06:42:12', '<!-- wp:paragraph -->\n<p>The <strong>Crop Biotechnology Center (CBC) </strong>is one of three biotechnology centers under the <strong>Department of Agriculture </strong>(DA). It serves as a catalyst in the development of and utilization of modern biotechnologies for agriculture. It rationalizes and implements the research, development, and extension agenda of the DA-Biotech Program. It also provides biotechnology capacity-building services to a network of R4D institution in the use of modern crop biotechnologies.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>DA-CBC</strong> focuses on applying advanced technologies that contribute to the improvement in performance, yield, and quality of important commodities, such as rice, corn, coconut, and high value crops, such as mango, garlic, onion, eggplant, tomato, cotton, rubber, cassava, sweet potato, yam, cacao, papaya, banana, and abaca.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {"textAlign":"center"} -->\n<h2 class="wp-block-heading has-text-align-center"><strong>R4D AREAS</strong></h2>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Genetics</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Genetic Engineering and Gene Editing</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Tissue Culture</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Microbial Biotechnology</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Diagnostics</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Bioinformatics and Computational Biology</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Natural Products, Natural Ingredients, and Value-Adding</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {"textAlign":"center"} -->\n<h2 class="wp-block-heading has-text-align-center">Laboratories</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p><strong>Molecular Genetics</strong><ul><li>Functional genomic approaches to accelerate crop breeding and production</li></ul></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->', 'What is DA-CBC?', '', 'inherit', 'closed', 'closed', '', '152-revision-v1', '', '', '2024-05-27 14:42:12', '2024-05-27 06:42:12', '', 152, 'http://localhost/?p=154', 0, 'revision', '', 0),
	(155, 1, '2024-05-27 14:42:21', '2024-05-27 06:42:21', '<!-- wp:paragraph -->\n<p>The <strong>Crop Biotechnology Center (CBC) </strong>is one of three biotechnology centers under the <strong>Department of Agriculture </strong>(DA). It serves as a catalyst in the development of and utilization of modern biotechnologies for agriculture. It rationalizes and implements the research, development, and extension agenda of the DA-Biotech Program. It also provides biotechnology capacity-building services to a network of R4D institution in the use of modern crop biotechnologies.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>DA-CBC</strong> focuses on applying advanced technologies that contribute to the improvement in performance, yield, and quality of important commodities, such as rice, corn, coconut, and high value crops, such as mango, garlic, onion, eggplant, tomato, cotton, rubber, cassava, sweet potato, yam, cacao, papaya, banana, and abaca.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {"textAlign":"center"} -->\n<h2 class="wp-block-heading has-text-align-center"><strong>R4D AREAS</strong></h2>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Genetics</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Genetic Engineering and Gene Editing</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Tissue Culture</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Microbial Biotechnology</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Diagnostics</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Bioinformatics and Computational Biology</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Natural Products, Natural Ingredients, and Value-Adding</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {"textAlign":"center"} -->\n<h2 class="wp-block-heading has-text-align-center"><strong>Laboratories</strong></h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p><strong>Molecular Genetics</strong><ul><li>Functional genomic approaches to accelerate crop breeding and production</li></ul></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->', 'What is DA-CBC?', '', 'inherit', 'closed', 'closed', '', '152-revision-v1', '', '', '2024-05-27 14:42:21', '2024-05-27 06:42:21', '', 152, 'http://localhost/?p=155', 0, 'revision', '', 0),
	(157, 1, '2024-05-27 15:03:40', '2024-05-27 07:03:40', '<!-- wp:paragraph -->\n<p>The <strong>Crop Biotechnology Center (CBC) </strong>is one of three biotechnology centers under the <strong>Department of Agriculture </strong>(DA). It serves as a catalyst in the development of and utilization of modern biotechnologies for agriculture. It rationalizes and implements the research, development, and extension agenda of the DA-Biotech Program. It also provides biotechnology capacity-building services to a network of R4D institution in the use of modern crop biotechnologies.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>DA-CBC</strong> focuses on applying advanced technologies that contribute to the improvement in performance, yield, and quality of important commodities, such as rice, corn, coconut, and high value crops, such as mango, garlic, onion, eggplant, tomato, cotton, rubber, cassava, sweet potato, yam, cacao, papaya, banana, and abaca.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {"textAlign":"center"} -->\n<h2 class="wp-block-heading has-text-align-center"><strong>R4D AREAS</strong></h2>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Genetics</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Genetic Engineering and Gene Editing</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Tissue Culture</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Microbial Biotechnology</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Diagnostics</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Bioinformatics and Computational Biology</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Natural Products, Natural Ingredients, and Value-Adding</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {"textAlign":"center"} -->\n<h2 class="wp-block-heading has-text-align-center"><strong>Laboratories</strong></h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p><strong>Molecular Genetics</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Functional genomic approaches to accelerate crop breeding and production</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Construction of detailed, high-resolution QTL maps and physical maps for map-based cloing</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p><strong>Genetic Transformation . </strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Use of genetic manipulation to improve traits of interest<strong> </strong></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Development of genetically modified (GM) and non-GM organisms, alterations to gene sequences, and gene knock-outs (RNAi)</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {"textAlign":"center"} -->\n<h2 class="wp-block-heading has-text-align-center"><strong>Tissue Culture</strong></h2>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Aseptic propagation of plant parts in a highly controlled environment </li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Creation of genetic variability for crop improvement</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {"textAlign":"center"} -->\n<h2 class="wp-block-heading has-text-align-center"><strong>Systems Biology (\'omics\')</strong></h2>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Systems biology approaches combining metabolomics with proteomics and/or transcriptomics</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Experimental strategies to characterize ribonucleic acid-protein complexes/interactions</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {"textAlign":"center"} -->\n<h2 class="wp-block-heading has-text-align-center"><strong>Microbial Biotechnology</strong></h2>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Use of plant-growth-promoting microorganisms (PGPM) as biofertilizers to enhance plant and soil health and biopesticide to control invasive plants and insects </li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {"textAlign":"center"} -->\n<h2 class="wp-block-heading has-text-align-center"><strong>Bioinformatics and Computational Biology</strong></h2>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Use of bioinformatics tools and high-performance computing systems and various computing support services to transform complex data into information useful to scientists </li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {"textAlign":"center"} -->\n<h2 class="wp-block-heading has-text-align-center">Molecular Diagnostic</h2>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Development of molecular tests, including biochemical, electrochemical, optical, and imaging-based, to diagnose diseases or other pathological conditions </li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {"textAlign":"center"} -->\n<h2 class="wp-block-heading has-text-align-center"><strong>TRAINING/ CONFERENCE VENUE</strong></h2>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Plenary Hall (Capacity:600 pax) </li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Multipurpose Hall (Сарасіtу: 300 рах) </li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Training Rooms (Capacity: 300 pax)</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->', 'What is DA-CBC?', '', 'inherit', 'closed', 'closed', '', '152-revision-v1', '', '', '2024-05-27 15:03:40', '2024-05-27 07:03:40', '', 152, 'http://localhost/?p=157', 0, 'revision', '', 0),
