wp:heading -->\n\n<!-- wp:media-text {"mediaId":573,"mediaLink":"http://localhost/rrsuralta/","mediaType":"image","mediaWidth":15} -->\n<div class="wp-block-media-text is-stacked-on-mobile" style="grid-template-columns:15% auto"><figure class="wp-block-media-text__media"><img src="http://localhost/wp-content/uploads/2024/06/RRSuralta-scaled-e1717643185253-1024x1024.jpg" alt="Dr. Roel R. Suralta" class="wp-image-573 size-full"/></figure><div class="wp-block-media-text__content"><!-- wp:html -->\n<p>\n<p>Dr. Roel R. Suralta</p>\n<i>2021- present</i>\n</p>\n<!-- /wp:html --></div></div>\n<!-- /wp:media-text --></div>\n<!-- /wp:group -->\n\n<!-- wp:block {"ref":192} /-->\n\n<!-- wp:heading -->\n<h2 class="wp-block-heading"><strong>CBC Staff</strong></h2>\n<!-- /wp:heading -->\n\n<!-- wp:html -->\n<div class="flex flex-wrap">\n<!-- /wp:html -->\n\n<!-- wp:html -->\n</div>\n<!-- /wp:html -->', 'Organization Structure', '', 'inherit', 'closed', 'closed', '', '149-revision-v1', '', '', '2024-06-10 11:26:22', '2024-06-10 03:26:22', '', 149, 'http://localhost/?p=783', 0, 'revision', '', 0),
