	(785, 1, '2024-06-10 11:27:42', '2024-06-10 03:27:42', '<!-- wp:heading {"level":1,"fontSize":"large"} -->\n<h1 class="wp-block-heading has-large-font-size"><strong>Organization Structure</strong></h1>\n<!-- /wp:heading -->\n\n<!-- wp:block {"ref":192} /-->\n\n<!-- wp:group {"layout":{"type":"constrained"}} -->\n<div class="wp-block-group"><!-- wp:heading {"level":3} -->\n<h3 class="wp-block-heading"><strong>Republic of the Philippines President</strong></h3>\n<!-- /wp:heading -->\n\n<!-- wp:media-text {"mediaId":674,"mediaLink":"http://localhost/bbm-profile-pic2/","mediaType":"image","mediaWidth":15} -->\n<div class="wp-block-media-text is-stacked-on-mobile" style="grid-template-columns:15% auto"><figure class="wp-block-media-text__media"><img src="http://localhost/wp-content/uploads/2024/06/BBM-Profile-Pic2.webp" alt="" class="wp-image-674 size-full"/></figure><div class="wp-block-media-text__content"><!-- wp:html -->\n<p>\n<p>President Bongbong Marcos Jr.</p>\n<i>2022 - present</i>\n</p>\n<!-- /wp:html --></div></div>\n<!-- /wp:media-text --></div>\n<!-- /wp:group -->\n\n<!-- wp:block {"ref":192} /-->\n\n<!-- wp:group {"layout":{"type":"constrained"}} -->\n<div class="wp-block-group"><!-- wp:heading {"level":3} -->\n<h3 class="wp-block-heading"><strong>Department of Agriculture Secretary&nbsp;</strong></h3>\n<!-- /wp:heading -->\n\n<!-- wp:media-text {"mediaId":694,"mediaLink":"http://localhost/about-us/organization-structure/francisco-tiu-laurel-jr/#main","mediaType":"image","mediaWidth":15} -->\n<div class="wp-block-media-text is-stacked-on-mobile" style="grid-template-columns:15% auto"><figure class="wp-block-media-text__media"><img src="http://localhost/wp-content/uploads/2024/06/Francisco-Tiu-Laurel-Jr.jpg" alt="" class="wp-image-694 size-full"/></figure><div class="wp-block-media-text__content"><!-- wp:html -->\n<p>\n<p>Secretary Francisco Tiu Laurel Jr.</p>\n<i>Secretary of Agriculture</i>\n</p>\n<!-- /wp:html --></div></div>\n<!-- /wp:media-text --></div