	(1089, 1, '2024-06-18 20:09:07', '2024-06-18 12:09:07', '<!-- wp:html -->\n<button class="accordion active">Department of Agriculture Attached Agencies</button>\n<div class="panel" style="max-height: 100vh;">\n<!-- /wp:html -->\n\n<!-- wp:block {"ref":192} /-->\n\n<!-- wp:media-text {"mediaId":542,"mediaLink":"http://localhost/da-bpo-1/","mediaType":"image","mediaWidth":15,"mediaSizeSlug":"full","verticalAlignment":"center","imageFill":false} -->\n<div class="wp-block-media-text is-stacked-on-mobile is-vertically-aligned-center" style="grid-template-columns:15% auto"><figure class="wp-block-media-text__media"><img src="http://localhost/wp-content/uploads/2024/06/DA-BPO-1.png" alt="DA BPO Logo" class="wp-image-542 size-full"/></figure><div class="wp-block-media-text__content"><!-- wp:paragraph {"placeholder":"Content…"} -->\n<p>Biotechnology Program Office (BPO)</p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:media-text -->\n\n<!-- wp:block {"ref":192} /-->\n\n<!-- wp:media-text {"mediaId":1078,"mediaLink":"http://localhost/fbc-logo/","mediaType":"image","mediaWidth":15,"verticalAlignment":"center"} -->\n<div class="wp-block-media-text is-stacked-on-mobile is-vertically-aligned-center" style="grid-template-columns:15% auto"><figure class="wp-block-media-text__media"><img src="http://localhost/wp-content/uploads/2024/06/FBC-Logo-1024x942.png" alt="" class="wp-image-1078 size-full"/></figure><div class="wp-block-media-text__content"><!-- wp:paragraph {"placeholder":"Content…"} -->\n<p>Fisheries Biotechnology Center (FBC)</p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:media-text -->\n\n<!-- wp:block {"ref":192} /-->\n\n<!-- wp:media-text {"mediaId":1077,"mediaLink":"http://localhost/lbc-logo/","mediaType":"image","mediaWidth":15,"verticalAlignment":"center"} -->\n<div class="wp-block-media-text is-stacked-on-mobile is-vertically-aligned-center" style="grid-template-columns:15% auto"><figure class="wp-block-media-text__media"><img src="http://localhost/wp-content/u