	(1180, 1, '2024-06-19 14:37:52', '2024-06-19 06:37:52', '{\n    "widget_block[82]": {\n        "value": {\n            "raw_instance": {\n                "content": "<div class=\\"flex items-center overflow-hidden w-full\\">\\n  <ul class=\\"slider flex flex-row gap-5 whitespace-nowrap bg-transparent h-fit m-0 p-2\\">\\n<li>\\n      <img class=\\"w-28 h-auto\\" src=\\"/wp-content/uploads/2024/06/FBC-Logo.png\\" />\\n    </li>\\n <li>\\n      <img class=\\"w-28 h-auto\\" src=\\"/wp-content/uploads/2024/06/LBC-Logo.png\\" />\\n</li>\\n  <li>\\n      <img class=\\"w-28 h-auto\\" src=\\"/wp-content/uploads/2024/06/PhilRiceDA-logo_standard-colored.png\\" />\\n    </li>\\n <li>\\n      <img class=\\"w-28 h-auto\\" src=\\"/wp-content/uploads/2024/06/PRRI-1.png\\" />\\n    </li>\\n  </ul>\\n</div>"\n            }\n        },\n        "type": "option",\n        "user_id": 1,\n        "date_modified_gmt": "2024-06-19 06:37:52"\n    }\n}', '', '', 'trash', 'closed', 'closed', '', '017da280-eb7e-4851-8a40-43a58d4c422d', '', '', '2024-06-19 14:37:52', '2024-06-19 06:37:52', '', 0, 'http://localhost/017da280-eb7e-4851-8a40-43a58d4c422d/', 0, 'customize_changeset', '', 0),
