	(1182, 1, '2024-06-19 15:03:16', '2024-06-19 07:03:16', '<!-- wp:details -->\n<details class="wp-block-details"><summary>Where are you located?</summary><!-- wp:paragraph {"placeholder":"Type / to add a hidden block"} -->\n<p>We are located at the DA-Philippine Rice Research Institute (PhilRice) Compound, Maligaya, Science City of Muñoz, 3119 Nueva Ecija.</p>\n<!-- /wp:paragraph --></details>\n<!-- /wp:details -->\n\n<!-- wp:details -->\n<details class="wp-block-details"><summary>What are your facilities?</summary><!-- wp:paragraph -->\n<p>The CBC has seven laboratories where different research activities are conducted: </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list {"className":"show-bullet"} -->\n<ul class="show-bullet"><!-- wp:list-item -->\n<li>Molecular Genetics</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Genetics Transformation</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Tissue Culture</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Systems Biology (\'omics\')</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Microbial Biotechnology</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Bioinformatics and Computational Biology</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Molecular Diagnostics</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:html -->\n<p>For more info visit the <a href="/visit-us/laboratories/">Laboratories</a></p>\n<!-- /wp:html --></details>\n<!-- /wp:details -->\n\n<!-- wp:details -->\n<details class="wp-block-details"><summary>How can I visit?</summary><!-- wp:html -->\n<p>\nPlease send a request letter addressed to DA-PhilRice Executive Director Dr. John C. de Leon for the attention of Dr, Roel R. Suralta, director if DA-CBC. You can send it to <a href="mailto:prri.mail.philrice.gov.ph">prri.mail.philrice.gov.ph</a> and CC <a href="mailto:cropbiotechcenter@gmail.com">cropbiotechcenter@gmail.com</a>.\n</p>\n</br>\n<p>\nIndicate the following information:\n<ul class="show-bullet">\n<li>Name (Individual/Organization)</li>\n<li>Objectives</li>\n<li>No. of participants</li>\n<li>Time and Date</li>\n<li>Contact person with an email address and mobile number</li>\n</ul>\n</p>\n</br>\n<p>Someone will be in touch with you once we recieve the letter.</p>\n<!-- /wp:html --></details>\n<!-- /wp:details -->\n\n<!-- wp:details -->\n<details class="wp-block-details"><summary>I need something else.</summary><!-- wp:paragraph {"placeholder":"Type / to add a hidden block"} -->\n<p>You can send your questions/concern at (+63) 908 889 7135 or cropbiotechcenter@gmail.com. Cheers!</p>\n<!-- /wp:paragraph --></details>\n<!-- /wp:details -->\n\n<!-- wp:details -->\n<details class="wp-block-details"><summary>What are you health and safety guidelines?</summary><!-- wp:html -->\n<p>Visitors are advised to strictly follow IATF Health and Safety Protocols for everyone\'s safety.</p>\n<p>They are reminded to:</p>\n<ul class="show-bullet">\n<li>send us copies of the vaccination certificates of those joining the activity</li>\n<li>ensure the proper wearing of face masks, physical distancing, & sanitation;</li>\n<li>note that minors and seniors are not allowed to visit unless they secure certification from LGU that they are allowed to go out in public</li>\n<li>restrict participants who experience any COVID19 symptoms (fever, cough, etc.)</li>\n</ul>\n<!-- /wp:html --></details>\n<!-- /wp:details -->\n\n<!-- wp:details -->\n<details class="wp-block-details"><summary>I want to conduct my On-the-Job Training/Immersion at your Center.</summary><!-- wp:html -->\n<p>\nTo proceed, kindly submit a letter addressed to Dr. Eduardo Jimmy P. Quilang, Deputy Executive Director for Research at the Philippine Rice Research Institute, signed by your OJT coordinator/Dean, then send to <a href="mailto:oc.domingo@mail.philrice.gov.ph">oc.domingo@mail.philrice.gov.ph</a>. Looking forward to your submission!\n</p>\n<!-- /wp:html --></details>\n<!-- /wp:details -->', 'FAQS', '', 'publish', 'closed', 'closed', '', 'faqs', '', '', '2024-06-19 16:04:39', '2024-06-19 08:04:39', '', 0, 'http://localhost/?page_id=1182', 0, 'page', '', 0),
	(1184, 1, '2024-06-19 15:03:16', '2024-06-19 07:03:16', '<!-- wp:details -->\n<details class="wp-block-details"><summary>Question 1</summary><!-- wp:paragraph {"placeholder":"Type / to add a hidden block"} -->\n<p></p>\n<!-- /wp:paragraph --></details>\n<!-- /wp:details -->\n\n<!-- wp:details -->\n<details class="wp-block-details"><summary>Question 2</summary><!-- wp:paragraph {"placeholder":"Type / to add a hidden block"} -->\n<p></p>\n<!-- /wp:paragraph --></details>\n<!-- /wp:details -->\n\n<!-- wp:details -->\n<details class="wp-block-details"><summary>Question 3</summary><!-- wp:paragraph {"placeholder":"Type / to add a hidden block"} -->\n<p></p>\n<!-- /wp:paragraph --></details>\n<!-- /wp:details -->', 'FAQS', '', 'inherit', 'closed', 'closed', '', '1182-revision-v1', '', '', '2024-06-19 15:03:16', '2024-06-19 07:03:16', '', 1182, 'http://localhost/?p=1184', 0, 'revision', '', 0),
	(1185, 1, '2024-06-19 16:01:43', '2024-06-19 08:01:43', '<!-- wp:details -->\n<details class="wp-block-details"><summary>Where are you located?</summary><!-- wp:paragraph {"placeholder":"Type / to add a hidden block"} -->\n<p>We are located at the DA-Philippine Rice Research Institute (PhilRice) Compound, Maligaya, Science City of Muñoz, 3119 Nueva Ecija.</p>\n<!-- /wp:paragraph --></details>\n<!-- /wp:details -->\n\n<!-- wp:details -->\n<details class="wp-block-details"><summary>What are your facilities?</summary><!-- wp:paragraph -->\n<p>The CBC has seven laboratories where different research activities are conducted: </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list {"className":"show-bullet"} -->\n<ul class="show-bullet"><!-- wp:list-item -->\n<li>Molecular Genetics</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Genetics Transformation</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Tissue Culture</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Systems Biology (\'omics\')</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Microbial Biotechnology</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Bioinformatics and Computational Biology</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Molecular Diagnostics</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:html -->\n<p>For more info visit the <a href="/visit-us/laboratories/">Laboratories</a></p>\n<!-- /wp:html --></details>\n<!-- /wp:details -->\n\n<!-- wp:details -->\n<details class="wp-block-details"><summary>How can I visit?</summary><!-- wp:html -->\n<p>\nPlease send a request letter addressed to DA-PhilRice Executive Director Dr. John C. de Leon for the attention of Dr, Roel R. Suralta, director if DA-CBC. You can send it to <a href="mailto:prri.mail.philrice.gov.ph">prri.mail.philrice.gov.ph</a> and CC <a href="mailto:cropbiotechcenter@gmail.com">cropbiotechcenter@gmail.com</a>.\n</p>\n</br>\n<p>\nIndicate the following information:\n<ul class="show-bullet">\n<li>Name (Individual/Organization)</li>\n<li>Objectives</li>\n<li>No. of participants</li>\n<li>Time and Date</li>\n<li>Contact person with an email address and mobile number</li>\n</ul>\n</p>\n</br>\n<p>Someone will be in touch with you once we recieve the letter.</p>\n<!-- /wp:html --></details>\n<!-- /wp:details -->\n\n<!-- wp:details -->\n<details class="wp-block-details"><summary>I need something else.</summary><!-- wp:paragraph {"placeholder":"Type / to add a hidden block"} -->\n<p>You can send your questions/concern at (+63) 908 889 7135 or cropbiotechcenter@gmail.com. Cheers!</p>\n<!-- /wp:paragraph --></details>\n<!-- /wp:details -->\n\n<!-- wp:details -->\n<details class="wp-block-details"><summary>What are you health and safety guidelines?</summary><!-- wp:html -->\n<p>Visitors are advised to strictly follow IATF Health and Safety Protocols for everyone\'s safety.</p>\n<p>They are reminded to:</p>\n<ul class="show-bullet">\n<li>send us copies of the vaccination certificates of those joining the activity</li>\n<li>ensure the proper wearing of face masks, physical distancing, & sanitation;</li>\n<li>note that minors and seniors are not allowed to visit unless they secure certification from LGU that they are allowed to go out in public</li>\n<li>restrict participants who experience any COVID19 symptoms (fever, cough, etc.)</li>\n</ul>\n<!-- /wp:html --></details>\n<!-- /wp:details -->\n\n<!-- wp:details -->\n<details class="wp-block-details"><summary>I want to conduct my On-the-Job Training/Immersion at your Center.</summary><!-- wp:html -->\n<p>\nTo proceed, kindly submit a letter addressed to Dr. Eduardo Jimmy P. Quilang, Deputy Executive Director for Research at the Philippine Rice Research Institute, signed by your OJT coordinator/Dean, then send to <a href="mailto:oc.domingo@mail.philrice.gov.ph">oc.domingo@mail.philrice.gov.ph</a>. Looking forward to your submission!\n</p>\n<!-- /wp:html --></details>\n<!-- /wp:details -->\n\n<!-- wp:shortcode /-->', 'FAQS', '', 'inherit', 'closed', 'closed', '', '1182-autosave-v1', '', '', '2024-06-19 16:01:43', '2024-06-19 08:01:43', '', 1182, 'http://localhost/?p=1185', 0, 'revision', '', 0),
